// GÜNÜN SÖZÜ havuzu (Ben ekranı > İçsel Harita). Kaynak: apps/bitkiler/src/data/quotes.json
// (Bitkiler/Taşlar'daki "günün sözü" ile AYNI havuz), 7 dil. Bitkiler'in engel listesi
// (akide/vaaz tonlu 7 söz, bkz. apps/bitkiler/src/utils/quotePool.ts) uygulandı ve yalnızca
// kısa sözler (Türkçe <=150 karakter) alındı: İçsel Harita'da bir bakışta okunmalı.
// Bitkiler'de veri değişirse burası elle yeniden üretilir. Dinamik import edilir (ana paket büyümez).
export const QUOTES = [
{"id": "q002", "s": "Mevlana Rumi", "t": {"tr": "Dün akıllıydım, dünyayı değiştirmek istiyordum. Bugün bilgeyim, kendimi değiştiriyorum.", "en": "Yesterday I was clever, so I wanted to change the world. Today I am wise, so I am changing myself.", "de": "Gestern war ich klug, darum wollte ich die Welt verändern. Heute bin ich weise, darum verändere ich mich selbst.", "es": "Ayer era inteligente, por eso quería cambiar el mundo. Hoy soy sabio, por eso me cambio a mí mismo.", "pt": "Ontem eu era esperto, por isso queria mudar o mundo. Hoje sou sábio, por isso mudo a mim mesmo.", "fr": "Hier j'étais intelligent, alors je voulais changer le monde. Aujourd'hui je suis sage, alors je me change moi-même.", "ja": "昨日の私は賢かったので、世界を変えたいと思った。今日の私は智慧を得たので、自分自身を変えている。"}},
{"id": "q003", "s": "Mevlana Rumi", "t": {"tr": "Ateşin içinde yanmayan şeyin hiçbir değeri yoktur.", "en": "Whatever does not burn in the fire has no worth.", "de": "Was nicht im Feuer brennt, hat keinen Wert.", "es": "Lo que no arde en el fuego no tiene valor.", "pt": "Aquilo que não arde no fogo não tem valor.", "fr": "Ce qui ne brûle pas dans le feu n'a aucune valeur.", "ja": "火の中で燃えないものに、価値はない。"}},
{"id": "q004", "s": "Mevlana Rumi", "t": {"tr": "Aşk gelince bütün eksiklikler gider. Aşk gelince utanç da gider, korku da.", "en": "When love arrives, all imperfections fall away. When love arrives, shame departs, and fear with it.", "de": "Wenn die Liebe kommt, fallen alle Unvollkommenheiten ab. Wenn die Liebe kommt, weicht die Scham, und mit ihr die Furcht.", "es": "Cuando llega el amor, caen todas las imperfecciones. Cuando llega el amor, se va la vergüenza, y con ella el miedo.", "pt": "Quando o amor chega, caem todas as imperfeições. Quando o amor chega, a vergonha parte, e com ela o medo.", "fr": "Quand l'amour arrive, toutes les imperfections tombent. Quand l'amour arrive, la honte s'en va, et la peur avec elle.", "ja": "愛が訪れると、すべての欠点は落ちていく。愛が訪れると、恥は去り、恐れもともに去る。"}},
{"id": "q005", "s": "Mevlana Rumi", "t": {"tr": "Sesin duyulmuyor diye ağlama. Belki de sesin tam çıkmayan yerden, sessizlikten çıkıyor.", "en": "Do not weep because your voice goes unheard. Perhaps your true voice rises from the silence itself.", "de": "Weine nicht, weil deine Stimme ungehört bleibt. Vielleicht erhebt sich deine wahre Stimme gerade aus der Stille selbst.", "es": "No llores porque tu voz no es escuchada. Quizá tu verdadera voz se eleve del propio silencio.", "pt": "Não chores porque a tua voz não é ouvida. Talvez a tua verdadeira voz se erga do próprio silêncio.", "fr": "Ne pleure pas parce que ta voix n'est pas entendue. Peut-être ta vraie voix s'élève-t-elle du silence même.", "ja": "声が届かないからと泣くな。あなたの真の声は、その沈黙そのものから立ちのぼるのかもしれない。"}},
{"id": "q006", "s": "Mevlana Rumi", "t": {"tr": "Hakikat güneş gibidir; perde çekersen gözden kaybolur ama güneş yine de oradadır.", "en": "Truth is like the sun; draw a veil over it and it disappears from sight, yet the sun remains where it always was.", "de": "Die Wahrheit ist wie die Sonne; verhülle sie, und sie verschwindet aus dem Blick, doch die Sonne bleibt, wo sie immer war.", "es": "La verdad es como el sol; échale un velo y desaparece de la vista, pero el sol sigue donde siempre estuvo.", "pt": "A verdade é como o sol; lança-lhe um véu e ela desaparece da vista, mas o sol permanece onde sempre esteve.", "fr": "La vérité est comme le soleil ; jette un voile sur elle et elle disparaît du regard, mais le soleil reste où il a toujours été.", "ja": "真実は太陽のようだ。覆いをかければ視界から消えるが、太陽はいつもの場所にとどまっている。"}},
{"id": "q007", "s": "Mevlana Rumi", "t": {"tr": "Biz neredeyiz? Sevgilinin bulunduğu yerde. Neyiz biz? Onun içinde bir damlacık.", "en": "Where are we? Wherever the Beloved is. What are we? A single droplet within Him.", "de": "Wo sind wir? Wo immer der Geliebte ist. Was sind wir? Ein einziger Tropfen in Ihm.", "es": "¿Dónde estamos? Donde esté el Amado. ¿Qué somos? Una sola gota dentro de Él.", "pt": "Onde estamos? Onde quer que esteja o Amado. O que somos? Uma única gota dentro Dele.", "fr": "Où sommes-nous ? Là où est l'Aimé. Que sommes-nous ? Une seule goutte en Lui.", "ja": "私たちはどこにいる？愛する者のいるところに。私たちとは何か？彼の中の一滴の雫。"}},
{"id": "q008", "s": "Mevlana Rumi", "t": {"tr": "Kendini bilen, Rabbini bilir.", "en": "Whoever knows themselves knows their Lord.", "de": "Wer sich selbst erkennt, erkennt seinen Herrn.", "es": "Quien se conoce a sí mismo conoce a su Señor.", "pt": "Quem conhece a si mesmo conhece o seu Senhor.", "fr": "Qui se connaît soi-même connaît son Seigneur.", "ja": "己を知る者は、その主を知る。"}},
{"id": "q009", "s": "Mevlana Rumi", "t": {"tr": "Bir mum diğer bir mumu tutuşturmakla ışığından bir şey yitirmez.", "en": "A candle loses nothing of its light by lighting another candle.", "de": "Eine Kerze verliert nichts von ihrem Licht, wenn sie eine andere Kerze entzündet.", "es": "Una vela no pierde nada de su luz al encender otra vela.", "pt": "Uma vela nada perde da sua luz ao acender outra vela.", "fr": "Une bougie ne perd rien de sa lumière en allumant une autre bougie.", "ja": "ろうそくは、別のろうそくに火を灯しても、その光を少しも失わない。"}},
{"id": "q010", "s": "Mevlana Rumi", "t": {"tr": "Kalp bir ayna gibidir. Onu pas tutmuşsa, ışık yansımaz. Ama cilalanınca her şeyi gösterir.", "en": "The heart is like a mirror. When rust covers it, no light reflects. But once polished, it reveals everything.", "de": "Das Herz ist wie ein Spiegel. Wenn Rost ihn bedeckt, spiegelt kein Licht. Doch einmal poliert, offenbart er alles.", "es": "El corazón es como un espejo. Cuando lo cubre el óxido, ninguna luz se refleja. Pero una vez pulido, lo revela todo.", "pt": "O coração é como um espelho. Quando a ferrugem o cobre, nenhuma luz se reflete. Mas, uma vez polido, revela tudo.", "fr": "Le cœur est comme un miroir. Quand la rouille le couvre, aucune lumière ne s'y reflète. Mais une fois poli, il révèle tout.", "ja": "心は鏡のようだ。錆が覆えば光は映らない。だが一度磨かれれば、すべてを映し出す。"}},
{"id": "q011", "s": "Mevlana Rumi", "t": {"tr": "İçinde bir nehir var; onu bulmak için çöle gitme.", "en": "There is a river within you; do not go to the desert to find it.", "de": "In dir ist ein Fluss; geh nicht in die Wüste, um ihn zu finden.", "es": "Hay un río dentro de ti; no vayas al desierto a buscarlo.", "pt": "Há um rio dentro de ti; não vás ao deserto procurá-lo.", "fr": "Il y a une rivière en toi ; ne va pas au désert pour la trouver.", "ja": "あなたの中に川がある。それを探しに砂漠へ行くな。"}},
{"id": "q012", "s": "Mevlana Rumi", "t": {"tr": "Sabır acıdır ama meyvesi tatlıdır.", "en": "Patience is bitter, but its fruit is sweet.", "de": "Geduld ist bitter, doch ihre Frucht ist süß.", "es": "La paciencia es amarga, pero su fruto es dulce.", "pt": "A paciência é amarga, mas o seu fruto é doce.", "fr": "La patience est amère, mais son fruit est doux.", "ja": "忍耐は苦いが、その実は甘い。"}},
{"id": "q013", "s": "Mevlana Rumi", "t": {"tr": "Ney, ayrılığı anlatır. Hepimiz birer neyiz, köküzden koparılmış.", "en": "The reed tells the tale of separation. We are all reeds, torn from our roots.", "de": "Das Rohr erzählt die Geschichte der Trennung. Wir alle sind Rohre, aus unseren Wurzeln gerissen.", "es": "La caña cuenta la historia de la separación. Todos somos cañas, arrancadas de nuestras raíces.", "pt": "A cana conta a história da separação. Somos todos canas, arrancadas de nossas raízes.", "fr": "Le roseau raconte l'histoire de la séparation. Nous sommes tous des roseaux, arrachés à nos racines.", "ja": "葦は別離の物語を語る。私たちは皆、根から引き裂かれた葦だ。"}},
{"id": "q014", "s": "Mevlana Rumi", "t": {"tr": "Susarsan lal olursun, konuşursan kelam olursun. Seç.", "en": "If you stay silent, you become mute; if you speak, you become the Word. Choose.", "de": "Bleibst du still, wirst du stumm; sprichst du, wirst du zum Wort. Wähle.", "es": "Si callas, te vuelves mudo; si hablas, te vuelves la Palabra. Elige.", "pt": "Se ficares calado, tornas-te mudo; se falares, tornas-te a Palavra. Escolhe.", "fr": "Si tu te tais, tu deviens muet ; si tu parles, tu deviens la Parole. Choisis.", "ja": "黙していれば、唖となる。語れば、言葉となる。選びなさい。"}},
{"id": "q016", "s": "Mevlana Rumi", "t": {"tr": "Kâinat bir kitaptır. Her yaprağında bir sır gizlidir.", "en": "The universe is a book. On every page a secret is hidden.", "de": "Das Universum ist ein Buch. Auf jeder Seite ist ein Geheimnis verborgen.", "es": "El universo es un libro. En cada página se oculta un secreto.", "pt": "O universo é um livro. Em cada página esconde-se um segredo.", "fr": "L'univers est un livre. Sur chaque page se cache un secret.", "ja": "宇宙は一冊の書だ。どの頁にも秘密が隠されている。"}},
{"id": "q017", "s": "Mevlana Rumi", "t": {"tr": "Aşk ateşiyle yanan, dünyayı değiştirir.", "en": "Whoever burns with the fire of love transforms the world.", "de": "Wer im Feuer der Liebe brennt, verwandelt die Welt.", "es": "Quien arde con el fuego del amor transforma el mundo.", "pt": "Quem arde com o fogo do amor transforma o mundo.", "fr": "Celui qui brûle du feu de l'amour transforme le monde.", "ja": "愛の火に燃える者は、世界を変える。"}},
{"id": "q018", "s": "Mevlana Rumi", "t": {"tr": "Herkes göründüğü gibi değildir; herkes gördüğü kadar görebilir.", "en": "No one is as they appear; each can see only as much as they themselves see.", "de": "Niemand ist, wie er erscheint; jeder kann nur so viel sehen, wie er selbst sieht.", "es": "Nadie es como parece; cada uno solo puede ver cuanto ve por sí mismo.", "pt": "Ninguém é como aparenta; cada um só consegue ver tanto quanto vê por si.", "fr": "Personne n'est tel qu'il paraît ; chacun ne peut voir qu'autant qu'il voit lui-même.", "ja": "誰も見かけ通りではない。人はそれぞれ、自分が見るだけしか見ることができない。"}},
{"id": "q019", "s": "Mevlana Rumi", "t": {"tr": "Ya olduğun gibi görün, ya göründüğün gibi ol.", "en": "Either appear as you are, or be as you appear.", "de": "Erscheine, wie du bist, oder sei, wie du erscheinst.", "es": "O muéstrate como eres, o sé como te muestras.", "pt": "Ou mostra-te como és, ou sê como te mostras.", "fr": "Ou parais tel que tu es, ou sois tel que tu parais.", "ja": "ありのままに現れるか、現れる通りであれ。"}},
{"id": "q020", "s": "Mevlana Rumi", "t": {"tr": "Yolun ortasında durma. Ortası yoktur yolun; ya ileri ya geri.", "en": "Do not stand still in the middle of the road. The road has no middle; either forward or back.", "de": "Bleib nicht in der Mitte des Weges stehen. Der Weg hat keine Mitte; entweder vorwärts oder zurück.", "es": "No te quedes parado en medio del camino. El camino no tiene medio; o adelante o atrás.", "pt": "Não fiques parado no meio do caminho. O caminho não tem meio; ou para a frente ou para trás.", "fr": "Ne reste pas immobile au milieu du chemin. Le chemin n'a pas de milieu ; soit en avant, soit en arrière.", "ja": "道の真ん中で立ち止まるな。道に真ん中はない。前へ進むか、後ろへ退くか。"}},
{"id": "q021", "s": "Şems-i Tebrizi", "t": {"tr": "Birlik şarabını içince, ayrılık acısı sona erer.", "en": "Once you drink the wine of unity, the pain of separation comes to an end.", "de": "Hast du einmal den Wein der Einheit getrunken, endet der Schmerz der Trennung.", "es": "Una vez que bebes el vino de la unidad, el dolor de la separación llega a su fin.", "pt": "Uma vez que bebas o vinho da unidade, a dor da separação chega ao fim.", "fr": "Une fois que tu bois le vin de l'unité, la douleur de la séparation prend fin.", "ja": "ひとたび一なるものの酒を飲めば、別離の痛みは終わりを迎える。"}},
{"id": "q022", "s": "Şems-i Tebrizi", "t": {"tr": "Korktuğun şeyin yanına git. Orada hazine bulursun.", "en": "Walk toward what you fear. There you will find treasure.", "de": "Geh auf das zu, was du fürchtest. Dort wirst du den Schatz finden.", "es": "Camina hacia lo que temes. Allí encontrarás el tesoro.", "pt": "Caminha em direção àquilo que temes. Ali encontrarás o tesouro.", "fr": "Marche vers ce que tu crains. Là tu trouveras le trésor.", "ja": "恐れるものへ向かって歩め。そこに宝を見いだすだろう。"}},
{"id": "q023", "s": "Şems-i Tebrizi", "t": {"tr": "Gerçek dost, seni olduğun gibi kabul eden değil, olabileceğin en iyi hale doğru çekendir.", "en": "A true friend is not one who accepts you as you are, but one who draws you toward the best you can become.", "de": "Ein wahrer Freund ist nicht der, der dich nimmt, wie du bist, sondern der dich zum Besten zieht, das du werden kannst.", "es": "Un verdadero amigo no es quien te acepta como eres, sino quien te impulsa hacia lo mejor que puedes llegar a ser.", "pt": "Um verdadeiro amigo não é aquele que te aceita como és, mas aquele que te impulsiona ao melhor que podes vir a ser.", "fr": "Un vrai ami n'est pas celui qui t'accepte tel que tu es, mais celui qui t'attire vers le meilleur que tu peux devenir.", "ja": "真の友とは、あなたをありのまま受け入れる者ではなく、あなたがなりうる最善へと引き上げる者だ。"}},
{"id": "q024", "s": "Şems-i Tebrizi", "t": {"tr": "Gölgeni bırak, güneşi takip et.", "en": "Leave your shadow behind and follow the sun.", "de": "Lass deinen Schatten hinter dir und folge der Sonne.", "es": "Deja tu sombra atrás y sigue al sol.", "pt": "Deixa a tua sombra para trás e segue o sol.", "fr": "Laisse ton ombre derrière toi et suis le soleil.", "ja": "影を後にして、太陽に従え。"}},
{"id": "q025", "s": "Şems-i Tebrizi", "t": {"tr": "İçindeki denizi fark et. Dışarıda pınar arama.", "en": "Notice the sea within you. Do not seek a spring outside.", "de": "Beachte das Meer in dir. Suche keine Quelle draußen.", "es": "Advierte el mar que hay en ti. No busques un manantial afuera.", "pt": "Repara no mar que há em ti. Não procures uma nascente lá fora.", "fr": "Remarque la mer en toi. Ne cherche pas une source au-dehors.", "ja": "あなたの中の海に気づきなさい。外に泉を求めるな。"}},
{"id": "q026", "s": "Şems-i Tebrizi", "t": {"tr": "Bir insan bir anda bile değişebilir. Bu değişime kapını açık tut.", "en": "A person can change in a single moment. Keep your door open to that change.", "de": "Ein Mensch kann sich in einem einzigen Augenblick wandeln. Halte deine Tür für diesen Wandel offen.", "es": "Una persona puede cambiar en un solo instante. Mantén tu puerta abierta a ese cambio.", "pt": "Uma pessoa pode mudar num único instante. Mantém a tua porta aberta a essa mudança.", "fr": "Une personne peut changer en un seul instant. Garde ta porte ouverte à ce changement.", "ja": "人はただ一瞬で変わりうる。その変化に扉を開けておきなさい。"}},
{"id": "q027", "s": "Şems-i Tebrizi", "t": {"tr": "Aşk bir ateştir; ya yakar dönüştürür, ya da yok eder.", "en": "Love is a fire; it either burns and transforms you, or it destroys you.", "de": "Die Liebe ist ein Feuer; entweder brennt sie und verwandelt dich, oder sie zerstört dich.", "es": "El amor es un fuego; o te quema y te transforma, o te destruye.", "pt": "O amor é um fogo; ou te queima e te transforma, ou te destrói.", "fr": "L'amour est un feu ; soit il te brûle et te transforme, soit il te détruit.", "ja": "愛は火だ。あなたを燃やして変えるか、滅ぼすかのどちらかだ。"}},
{"id": "q028", "s": "Şems-i Tebrizi", "t": {"tr": "Sessizlik bazen en derin konuşmadır.", "en": "Silence is sometimes the deepest of all conversations.", "de": "Stille ist manchmal das tiefste aller Gespräche.", "es": "El silencio es a veces la más profunda de todas las conversaciones.", "pt": "O silêncio é, por vezes, a mais profunda de todas as conversas.", "fr": "Le silence est parfois la plus profonde de toutes les conversations.", "ja": "沈黙は時に、あらゆる会話の中で最も深いものだ。"}},
{"id": "q029", "s": "Şems-i Tebrizi", "t": {"tr": "Seni en iyi tanıyan, sana en çok zorluk çıkarandır. Çünkü o seni dönüştürür.", "en": "The one who knows you best is the one who challenges you the most. For that one transforms you.", "de": "Der, der dich am besten kennt, ist der, der dich am meisten herausfordert. Denn er verwandelt dich.", "es": "Quien mejor te conoce es quien más te desafía. Pues ese te transforma.", "pt": "Quem melhor te conhece é quem mais te desafia. Pois esse te transforma.", "fr": "Celui qui te connaît le mieux est celui qui te met le plus à l'épreuve. Car celui-là te transforme.", "ja": "あなたを最もよく知る者は、あなたを最も試す者だ。その者があなたを変えるのだから。"}},
{"id": "q030", "s": "Şems-i Tebrizi", "t": {"tr": "Nur, karanlığın içinden gelir. Karanlıktan kaçma.", "en": "Light comes through the darkness. Do not flee the dark.", "de": "Das Licht kommt durch die Dunkelheit. Fliehe nicht vor dem Dunkel.", "es": "La luz llega a través de la oscuridad. No huyas de lo oscuro.", "pt": "A luz vem através da escuridão. Não fujas do escuro.", "fr": "La lumière vient à travers les ténèbres. Ne fuis pas l'obscurité.", "ja": "光は闇を通して来る。闇から逃げるな。"}},
{"id": "q031", "s": "Şems-i Tebrizi", "t": {"tr": "Her nefes bir hediyedir; farkında mısın?", "en": "Each breath is a gift; are you aware of it?", "de": "Jeder Atemzug ist ein Geschenk; bist du dir dessen bewusst?", "es": "Cada aliento es un regalo; ¿eres consciente de ello?", "pt": "Cada respiração é um presente; estás ciente disso?", "fr": "Chaque souffle est un présent ; en es-tu conscient ?", "ja": "ひと息ひと息が贈り物だ。あなたはそれに気づいているか。"}},
{"id": "q032", "s": "Şems-i Tebrizi", "t": {"tr": "Kalbinde ne varsa, dilin onu konuşur.", "en": "Whatever is in your heart, your tongue will speak.", "de": "Was in deinem Herzen ist, wird deine Zunge sprechen.", "es": "Lo que haya en tu corazón, tu lengua lo hablará.", "pt": "O que houver no teu coração, a tua língua falará.", "fr": "Ce qui est dans ton cœur, ta langue le dira.", "ja": "心にあるものを、舌は語る。"}},
{"id": "q033", "s": "Şems-i Tebrizi", "t": {"tr": "Yüz kere düşsen de, yüz bir kere kalk.", "en": "Though you fall a hundred times, rise a hundred and one.", "de": "Auch wenn du hundertmal fällst, erhebe dich einhundertundeinmal.", "es": "Aunque caigas cien veces, levántate ciento una.", "pt": "Ainda que caias cem vezes, ergue-te cento e uma.", "fr": "Même si tu tombes cent fois, relève-toi cent une fois.", "ja": "百度倒れても、百一度立ち上がれ。"}},
{"id": "q034", "s": "Yunus Emre", "t": {"tr": "Ben Yunus'um, bu dünyaya bir kez gelirim. Sevgiyi bırakacak ne var ki geride?", "en": "I am Yunus, I come to this world but once. What is there to leave behind but love?", "de": "Ich bin Yunus, ich komme nur einmal in diese Welt. Was bleibt zu hinterlassen außer Liebe?", "es": "Soy Yunus, vengo a este mundo una sola vez. ¿Qué hay que dejar atrás sino amor?", "pt": "Sou Yunus, venho a este mundo apenas uma vez. O que há para deixar senão amor?", "fr": "Je suis Yunus, je ne viens qu'une fois en ce monde. Que reste-t-il à laisser sinon l'amour ?", "ja": "私はユヌス、この世に来るのはただ一度。愛のほかに、遺すものなどあろうか。"}},
{"id": "q035", "s": "Yunus Emre", "t": {"tr": "Ben gelmedim dava için, benim işim sevi için. Dost'un evi gönüllerdir, gönüller yapmaya geldim.", "en": "I came not for quarrel; my work is love. The house of the Beloved is in hearts, and I came to build hearts.", "de": "Ich kam nicht zum Streit; mein Werk ist die Liebe. Das Haus des Geliebten ist in den Herzen, und ich kam, um Herzen zu bauen.", "es": "No vine a reñir; mi labor es el amor. La casa del Amado está en los corazones, y vine a construir corazones.", "pt": "Não vim para a briga; o meu trabalho é o amor. A casa do Amado está nos corações, e vim construir corações.", "fr": "Je ne suis pas venu pour la querelle ; mon œuvre est l'amour. La maison de l'Aimé est dans les cœurs, et je suis venu bâtir des cœurs.", "ja": "私は争いのために来たのではない。私の仕事は愛だ。愛する者の家は心の中にあり、私は心を築くために来た。"}},
{"id": "q036", "s": "Yunus Emre", "t": {"tr": "Sevelim sevilelim; bu dünya kimseye kalmaz.", "en": "Let us love and be loved; this world is for no one to keep.", "de": "Lasst uns lieben und geliebt werden; diese Welt gehört keinem für immer.", "es": "Amemos y seamos amados; este mundo no es de nadie para conservarlo.", "pt": "Amemos e sejamos amados; este mundo não é de ninguém para guardar.", "fr": "Aimons et soyons aimés ; ce monde n'est à personne pour le garder.", "ja": "愛し、愛されよう。この世は誰のものとしてとどまるものでもない。"}},
{"id": "q037", "s": "Yunus Emre", "t": {"tr": "İlim ilim bilmektir, ilim kendin bilmektir. Sen kendini bilmezsen, bu nice okumaktır.", "en": "Knowledge is to know knowledge; knowledge is to know oneself. If you do not know yourself, what good is all this reading?", "de": "Wissen ist, das Wissen zu kennen; Wissen ist, sich selbst zu kennen. Wenn du dich selbst nicht kennst, was nützt all das Lesen?", "es": "El conocimiento es conocer el conocimiento; el conocimiento es conocerse a uno mismo. Si no te conoces a ti, ¿de qué sirve tanta lectura?", "pt": "O conhecimento é conhecer o conhecimento; o conhecimento é conhecer a si mesmo. Se não te conheces, de que serve toda essa leitura?", "fr": "Le savoir, c'est connaître le savoir ; le savoir, c'est se connaître soi-même. Si tu ne te connais pas, à quoi bon toutes ces lectures ?", "ja": "知とは知を知ること。知とは己を知ること。己を知らねば、あれほどの読書が何の役に立とう。"}},
{"id": "q038", "s": "Yunus Emre", "t": {"tr": "Bir kez gönül yıktıysan, kıldığın namaz değil. Yetmiş iki millet bile etmez o günahı.", "en": "If you break a heart even once, your prayers are not prayers. Not even seventy-two nations can absolve that sin.", "de": "Brichst du ein Herz auch nur einmal, sind deine Gebete keine Gebete. Nicht einmal zweiundsiebzig Völker können diese Sünde tilgen.", "es": "Si rompes un corazón aunque sea una vez, tus oraciones no son oraciones. Ni siquiera setenta y dos naciones pueden absolver ese pecado.", "pt": "Se partires um coração ao menos uma vez, as tuas orações não são orações. Nem mesmo setenta e duas nações podem absolver esse pecado.", "fr": "Si tu brises un cœur ne serait-ce qu'une fois, tes prières ne sont pas des prières. Même soixante-douze nations ne peuvent absoudre ce péché.", "ja": "ただ一度でも心を傷つければ、あなたの祈りは祈りではない。七十二の民族をもってしても、その罪は赦せない。"}},
{"id": "q039", "s": "Yunus Emre", "t": {"tr": "Cennet cennet dedikleri birkaç köşkle birkaç huri. İsteyene ver sen anı, bana seni gerek seni.", "en": "What they call paradise is a few mansions and a few houris. Give it to whoever wants it; what I want is You, only You.", "de": "Was sie Paradies nennen, sind ein paar Villen und ein paar Huris. Gib es, wem es begehrt; was ich will, bist Du, nur Du.", "es": "Lo que llaman paraíso son unas mansiones y unas huríes. Dáselo a quien lo quiera; lo que yo quiero eres Tú, solo Tú.", "pt": "O que chamam de paraíso são algumas mansões e algumas húris. Dá-o a quem o quiser; o que eu quero és Tu, só Tu.", "fr": "Ce qu'ils appellent paradis n'est que quelques demeures et quelques houris. Donne-le à qui le veut ; ce que je veux, c'est Toi, rien que Toi.", "ja": "彼らが楽園と呼ぶものは、いくつかの館といくつかの天女。欲しい者にやればよい。私が欲しいのはあなた、ただあなただけ。"}},
{"id": "q040", "s": "Yunus Emre", "t": {"tr": "Ete kemiğe büründüm, Yunus diye göründüm.", "en": "I clothed myself in flesh and bone, and appeared as Yunus.", "de": "Ich kleidete mich in Fleisch und Bein und erschien als Yunus.", "es": "Me vestí de carne y hueso, y aparecí como Yunus.", "pt": "Vesti-me de carne e osso, e apareci como Yunus.", "fr": "Je me suis vêtu de chair et d'os, et je suis apparu sous le nom de Yunus.", "ja": "私は肉と骨をまとい、ユヌスとして現れた。"}},
{"id": "q041", "s": "Yunus Emre", "t": {"tr": "Aşkın aldı benden beni, bana seni gerek seni.", "en": "Your love has taken me from myself; what I need is You, only You.", "de": "Deine Liebe hat mich von mir selbst genommen; was ich brauche, bist Du, nur Du.", "es": "Tu amor me ha apartado de mí mismo; lo que necesito eres Tú, solo Tú.", "pt": "O teu amor tirou-me de mim mesmo; o que preciso és Tu, só Tu.", "fr": "Ton amour m'a pris à moi-même ; ce dont j'ai besoin, c'est Toi, rien que Toi.", "ja": "あなたの愛が私を私自身から奪った。私に必要なのはあなた、ただあなただけ。"}},
{"id": "q042", "s": "Yunus Emre", "t": {"tr": "Dost elinden içtim şarap, bende kalmadı hesap.", "en": "I drank wine from the hand of the Beloved; no reckoning remains in me.", "de": "Ich trank Wein aus der Hand des Geliebten; keine Rechenschaft bleibt mehr in mir.", "es": "Bebí vino de la mano del Amado; ya no queda cuenta alguna en mí.", "pt": "Bebi vinho da mão do Amado; já não resta conta alguma em mim.", "fr": "J'ai bu le vin de la main de l'Aimé ; il ne reste plus en moi aucun compte à rendre.", "ja": "私は愛する者の手から酒を飲んだ。もはや私の中に勘定は残っていない。"}},
{"id": "q043", "s": "Yunus Emre", "t": {"tr": "Benim ile ün ü sanım, gönlümdeki dost dostum.", "en": "My name and renown are with me; the friend in my heart is my truest friend.", "de": "Mein Name und mein Ruhm sind bei mir; der Freund in meinem Herzen ist mein wahrster Freund.", "es": "Mi nombre y mi fama están conmigo; el amigo en mi corazón es mi amigo más verdadero.", "pt": "O meu nome e a minha fama estão comigo; o amigo no meu coração é o meu amigo mais verdadeiro.", "fr": "Mon nom et ma renommée sont avec moi ; l'ami dans mon cœur est mon ami le plus vrai.", "ja": "名も誉れも私とともにある。私の心の中の友こそ、最も真の友だ。"}},
{"id": "q044", "s": "Yunus Emre", "t": {"tr": "Adım adım benden öte, bana taş atan kişinin. Her attığı benim için, gül demeye başladım.", "en": "Step by step beyond myself I go. For each stone thrown at me, I have begun to say: a rose.", "de": "Schritt für Schritt gehe ich über mich selbst hinaus. Für jeden Stein, der nach mir geworfen wird, habe ich begonnen zu sagen: eine Rose.", "es": "Paso a paso más allá de mí mismo voy. Por cada piedra que me arrojan, he empezado a decir: una rosa.", "pt": "Passo a passo, para além de mim mesmo eu vou. Por cada pedra que me atiram, comecei a dizer: uma rosa.", "fr": "Pas à pas, je vais au-delà de moi-même. À chaque pierre qu'on me jette, j'ai commencé à dire : une rose.", "ja": "一歩ずつ、私は自分を越えていく。私に投げられる石の一つひとつに、私は「バラだ」と言い始めた。"}},
{"id": "q045", "s": "Yunus Emre", "t": {"tr": "Ne ararsan kendinde ara. Kudüs'te Mekke'de değil.", "en": "Whatever you seek, seek within yourself. Not in Jerusalem, not in Mecca.", "de": "Was du auch suchst, suche es in dir selbst. Nicht in Jerusalem, nicht in Mekka.", "es": "Lo que busques, búscalo dentro de ti. No en Jerusalén, ni en La Meca.", "pt": "O que quer que busques, busca-o dentro de ti. Não em Jerusalém, nem em Meca.", "fr": "Quoi que tu cherches, cherche-le en toi-même. Ni à Jérusalem, ni à La Mecque.", "ja": "何を求めるにせよ、自分の中に求めよ。エルサレムでもなく、メッカでもなく。"}},
{"id": "q046", "s": "Yunus Emre", "t": {"tr": "Şu dünya bir pınar gibidir, içenler doymaz.", "en": "This world is like a spring; those who drink are never satisfied.", "de": "Diese Welt ist wie eine Quelle; wer trinkt, wird niemals satt.", "es": "Este mundo es como un manantial; quienes beben nunca quedan saciados.", "pt": "Este mundo é como uma nascente; quem bebe nunca se sacia.", "fr": "Ce monde est comme une source ; ceux qui boivent ne sont jamais rassasiés.", "ja": "この世は泉のようだ。飲む者は決して満たされない。"}},
{"id": "q047", "s": "Yunus Emre", "t": {"tr": "Gönlüm bir bülbül gibi, dost bahçesinde öter.", "en": "My heart is like a nightingale that sings in the Beloved's garden.", "de": "Mein Herz ist wie eine Nachtigall, die im Garten des Geliebten singt.", "es": "Mi corazón es como un ruiseñor que canta en el jardín del Amado.", "pt": "O meu coração é como um rouxinol que canta no jardim do Amado.", "fr": "Mon cœur est comme un rossignol qui chante dans le jardin de l'Aimé.", "ja": "私の心は、愛する者の庭でさえずるナイチンゲールのようだ。"}},
{"id": "q048", "s": "Yunus Emre", "t": {"tr": "Söz ola kese savaşı, söz ola kestire başı. Söz ola ağulu aşı, yağ ile bal eyleye.", "en": "A word can end a war, a word can sever a head. A word can turn bitter poison into honey and oil.", "de": "Ein Wort kann einen Krieg beenden, ein Wort kann ein Haupt abtrennen. Ein Wort kann bitteres Gift in Honig und Öl verwandeln.", "es": "Una palabra puede acabar una guerra, una palabra puede cortar una cabeza. Una palabra puede volver miel y aceite el veneno amargo.", "pt": "Uma palavra pode acabar uma guerra, uma palavra pode cortar uma cabeça. Uma palavra pode tornar mel e óleo o veneno amargo.", "fr": "Un mot peut mettre fin à une guerre, un mot peut trancher une tête. Un mot peut changer un poison amer en miel et en huile.", "ja": "一言が戦を終わらせ、一言が首を落とす。一言が苦い毒を蜜と油に変える。"}},
{"id": "q049", "s": "Yunus Emre", "t": {"tr": "Bir ben vardır bende benden içeru.", "en": "There is an I within me, deeper than myself.", "de": "In mir ist ein Ich, tiefer als ich selbst.", "es": "Hay un yo dentro de mí, más hondo que yo mismo.", "pt": "Há um eu dentro de mim, mais profundo do que eu mesmo.", "fr": "Il y a un moi en moi, plus profond que moi-même.", "ja": "私の中に、私自身より深い「私」がいる。"}},
{"id": "q050", "s": "Yunus Emre", "t": {"tr": "Hak'tan gelen şerbeti içtik elhamdülillah.", "en": "We have drunk the sherbet that comes from the Truth, praise be to God.", "de": "Wir haben den Sirup getrunken, der von der Wahrheit kommt, gelobt sei Gott.", "es": "Hemos bebido el sorbete que viene de la Verdad, alabado sea Dios.", "pt": "Bebemos o xarope que vem da Verdade, louvado seja Deus.", "fr": "Nous avons bu le sirop qui vient de la Vérité, louange à Dieu.", "ja": "私たちは真実から来る甘露を飲んだ。神に讃えあれ。"}},
{"id": "q051", "s": "Hacı Bektaş Veli", "t": {"tr": "Hararet nardadır, sacda değil. Keramet baştadır, taçta değil.", "en": "The heat is in the fire, not in the pan. The grace is in the head, not in the crown.", "de": "Die Hitze ist im Feuer, nicht in der Pfanne. Die Gnade ist im Haupt, nicht in der Krone.", "es": "El calor está en el fuego, no en la sartén. La gracia está en la cabeza, no en la corona.", "pt": "O calor está no fogo, não na panela. A graça está na cabeça, não na coroa.", "fr": "La chaleur est dans le feu, non dans la poêle. La grâce est dans la tête, non dans la couronne.", "ja": "熱は火の中にあり、鍋の中にはない。恵みは頭の中にあり、冠の中にはない。"}},
{"id": "q052", "s": "Hacı Bektaş Veli", "t": {"tr": "Eline, beline, diline sahip ol.", "en": "Master your hand, your loins, and your tongue.", "de": "Beherrsche deine Hand, deine Lenden und deine Zunge.", "es": "Domina tu mano, tus entrañas y tu lengua.", "pt": "Domina a tua mão, as tuas entranhas e a tua língua.", "fr": "Maîtrise ta main, tes reins et ta langue.", "ja": "己の手と、腰と、舌を治めよ。"}},
{"id": "q053", "s": "Hacı Bektaş Veli", "t": {"tr": "Okunacak en büyük kitap insandır.", "en": "The greatest book to be read is the human being.", "de": "Das größte Buch, das es zu lesen gilt, ist der Mensch.", "es": "El mayor libro que se ha de leer es el ser humano.", "pt": "O maior livro a ser lido é o ser humano.", "fr": "Le plus grand livre à lire est l'être humain.", "ja": "読むべき最も偉大な書は、人間そのものだ。"}},
{"id": "q054", "s": "Hacı Bektaş Veli", "t": {"tr": "Kadınları okutunuz. Bir milleti kurtarmak için evvela analarını irfanlı yetiştirmek lazımdır.", "en": "Educate your women. To save a nation, one must first raise its mothers in wisdom.", "de": "Bildet eure Frauen. Um ein Volk zu retten, muss man zuerst seine Mütter in Weisheit erziehen.", "es": "Educa a tus mujeres. Para salvar a una nación, primero hay que criar a sus madres en la sabiduría.", "pt": "Educa as tuas mulheres. Para salvar uma nação, é preciso primeiro criar as suas mães na sabedoria.", "fr": "Éduque tes femmes. Pour sauver une nation, il faut d'abord élever ses mères dans la sagesse.", "ja": "あなたの女性たちを教育せよ。国を救うには、まずその母たちを智慧のうちに育てねばならない。"}},
{"id": "q055", "s": "Hacı Bektaş Veli", "t": {"tr": "Mürşidin sözü, suyun taşı yalaması gibidir. Yavaş ama emin.", "en": "The word of the master is like water wearing away a stone. Slow, but sure.", "de": "Das Wort des Meisters ist wie Wasser, das einen Stein aushöhlt. Langsam, doch gewiss.", "es": "La palabra del maestro es como el agua que desgasta una piedra. Lenta, pero segura.", "pt": "A palavra do mestre é como a água que desgasta a pedra. Lenta, mas certa.", "fr": "La parole du maître est comme l'eau qui use une pierre. Lente, mais sûre.", "ja": "師の言葉は、石をすり減らす水のようだ。ゆっくりと、しかし確かに。"}},
{"id": "q056", "s": "Hacı Bektaş Veli", "t": {"tr": "Gönül Çalab'ın tahtı, Çalab gönüle baktı.", "en": "The heart is the throne of God; God looked upon the heart.", "de": "Das Herz ist der Thron Gottes; Gott blickte auf das Herz.", "es": "El corazón es el trono de Dios; Dios miró al corazón.", "pt": "O coração é o trono de Deus; Deus olhou para o coração.", "fr": "Le cœur est le trône de Dieu ; Dieu a regardé le cœur.", "ja": "心は神の御座。神は心をご覧になった。"}},
{"id": "q057", "s": "Hacı Bektaş Veli", "t": {"tr": "Her ne ararsan arayı arayı. Kendinden başka bir şey bulamazsın.", "en": "Search and search for whatever you seek. You will find nothing but yourself.", "de": "Suche und suche, was du auch suchst. Du wirst nichts als dich selbst finden.", "es": "Busca y busca lo que busques. No hallarás más que a ti mismo.", "pt": "Procura e procura o que quer que busques. Nada encontrarás senão a ti mesmo.", "fr": "Cherche et cherche encore ce que tu cherches. Tu ne trouveras rien d'autre que toi-même.", "ja": "何を求めようと、探して、探し続けよ。己自身のほかには何も見いださないだろう。"}},
{"id": "q059", "s": "Hacı Bektaş Veli", "t": {"tr": "İncinsen de incitme.", "en": "Though you be wounded, wound no one.", "de": "Auch wenn du verwundet bist, verwunde keinen.", "es": "Aunque estés herido, no hieras a nadie.", "pt": "Ainda que estejas ferido, não firas ninguém.", "fr": "Même blessé, ne blesse personne.", "ja": "たとえ傷ついても、誰も傷つけるな。"}},
{"id": "q060", "s": "Hacı Bektaş Veli", "t": {"tr": "Dünya gamı çekmek, ahiret için hazırlanmak değildir. Şimdi yap iyi olanı.", "en": "To bear the world's sorrow is not the same as preparing for the hereafter. Do the good now.", "de": "Den Kummer der Welt zu tragen ist nicht dasselbe wie sich auf das Jenseits vorzubereiten. Tu das Gute jetzt.", "es": "Cargar con el dolor del mundo no es lo mismo que prepararse para el más allá. Haz el bien ahora.", "pt": "Carregar a tristeza do mundo não é o mesmo que preparar-se para o além. Faz o bem agora.", "fr": "Porter le chagrin du monde n'est pas la même chose que se préparer à l'au-delà. Fais le bien maintenant.", "ja": "世の憂いを背負うことは、来世に備えることと同じではない。善は今、行え。"}},
{"id": "q061", "s": "Hacı Bektaş Veli", "t": {"tr": "Kul hatasını bilirse, Hak affeder.", "en": "If the servant knows their fault, the Truth forgives.", "de": "Wenn der Diener seinen Fehler erkennt, vergibt die Wahrheit.", "es": "Si el siervo conoce su falta, la Verdad perdona.", "pt": "Se o servo conhece a sua falta, a Verdade perdoa.", "fr": "Si le serviteur connaît sa faute, la Vérité pardonne.", "ja": "僕がその過ちを知れば、真実は赦したまう。"}},
{"id": "q062", "s": "Hacı Bektaş Veli", "t": {"tr": "Şu dünya fanidir. Temelden inşa ettiğin gönlü yap.", "en": "This world is fleeting. Build the heart you raise from its foundation.", "de": "Diese Welt ist vergänglich. Baue das Herz, das du errichtest, von Grund auf.", "es": "Este mundo es fugaz. Construye desde sus cimientos el corazón que levantas.", "pt": "Este mundo é passageiro. Constrói desde os alicerces o coração que ergues.", "fr": "Ce monde est éphémère. Bâtis dès ses fondations le cœur que tu élèves.", "ja": "この世は移ろう。あなたが築き上げる心を、その土台から建てよ。"}},
{"id": "q063", "s": "Hacı Bektaş Veli", "t": {"tr": "Kırklar meclisinde içilen şarap sevgi şarabıdır.", "en": "The wine drunk in the gathering of the Forty is the wine of love.", "de": "Der Wein, der in der Versammlung der Vierzig getrunken wird, ist der Wein der Liebe.", "es": "El vino que se bebe en la reunión de los Cuarenta es el vino del amor.", "pt": "O vinho que se bebe na reunião dos Quarenta é o vinho do amor.", "fr": "Le vin bu dans l'assemblée des Quarante est le vin de l'amour.", "ja": "四十人の集いで飲まれる酒は、愛の酒だ。"}},
{"id": "q064", "s": "Hacı Bektaş Veli", "t": {"tr": "Alim olmak kolaydır, insan olmak zordur.", "en": "It is easy to be a scholar; it is hard to be a human being.", "de": "Es ist leicht, ein Gelehrter zu sein; es ist schwer, ein Mensch zu sein.", "es": "Es fácil ser un erudito; es difícil ser un ser humano.", "pt": "É fácil ser um erudito; é difícil ser um ser humano.", "fr": "Il est facile d'être un savant ; il est difficile d'être un être humain.", "ja": "学者であることはたやすい。人間であることは難しい。"}},
{"id": "q109", "s": "Aşık Veysel", "t": {"tr": "Aşık Veysel'im, bağlar beni bu toprağa. Bu toprak benim, ben bu toprağım.", "en": "I am Aşık Veysel, bound to this earth. This earth is mine, and I am this earth.", "de": "Ich bin Aşık Veysel, an diese Erde gebunden. Diese Erde ist mein, und ich bin diese Erde.", "es": "Soy Aşık Veysel, ligado a esta tierra. Esta tierra es mía, y yo soy esta tierra.", "pt": "Sou Aşık Veysel, ligado a esta terra. Esta terra é minha, e eu sou esta terra.", "fr": "Je suis Aşık Veysel, lié à cette terre. Cette terre est mienne, et je suis cette terre.", "ja": "私はアーシュク・ヴェイセル、この大地に結ばれている。この大地は私のもの、そして私はこの大地だ。"}},
{"id": "q110", "s": "Aşık Veysel", "t": {"tr": "Gözlerim görmese de gönlüm görür. Gerçek ışık içten gelir.", "en": "Though my eyes do not see, my heart sees. True light comes from within.", "de": "Auch wenn meine Augen nicht sehen, sieht mein Herz. Wahres Licht kommt von innen.", "es": "Aunque mis ojos no vean, mi corazón ve. La verdadera luz viene de dentro.", "pt": "Ainda que os meus olhos não vejam, o meu coração vê. A verdadeira luz vem de dentro.", "fr": "Même si mes yeux ne voient pas, mon cœur voit. La vraie lumière vient de l'intérieur.", "ja": "私の目は見えずとも、私の心は見る。真の光は内から来る。"}},
{"id": "q111", "s": "Aşık Veysel", "t": {"tr": "Uzun ince bir yoldayım, gidiyorum gündüz gece.", "en": "I walk a long and narrow road, going on by day and by night.", "de": "Ich gehe einen langen und schmalen Weg, bei Tag und bei Nacht.", "es": "Recorro un camino largo y estrecho, andando de día y de noche.", "pt": "Percorro um caminho longo e estreito, seguindo de dia e de noite.", "fr": "Je parcours un chemin long et étroit, avançant de jour et de nuit.", "ja": "私は長く細い道を歩む、昼も夜も進みながら。"}},
{"id": "q112", "s": "Aşık Veysel", "t": {"tr": "Bahçemizde gül biter, bülbüller öter. Güzellik bitimsizdir.", "en": "Roses bloom in our garden, nightingales sing. Beauty has no end.", "de": "In unserem Garten blühen Rosen, Nachtigallen singen. Die Schönheit hat kein Ende.", "es": "En nuestro jardín florecen rosas, cantan los ruiseñores. La belleza no tiene fin.", "pt": "No nosso jardim florescem rosas, cantam rouxinóis. A beleza não tem fim.", "fr": "Dans notre jardin fleurissent les roses, chantent les rossignols. La beauté n'a pas de fin.", "ja": "私たちの庭にはバラが咲き、ナイチンゲールがさえずる。美に終わりはない。"}},
{"id": "q113", "s": "Aşık Veysel", "t": {"tr": "En güzel köy senin büyüdüğün, en güzel ana senin anan.", "en": "The most beautiful village is the one where you grew up; the most beautiful mother is your own.", "de": "Das schönste Dorf ist das, in dem du aufgewachsen bist; die schönste Mutter ist deine eigene.", "es": "El pueblo más hermoso es aquel donde creciste; la madre más hermosa es la tuya.", "pt": "A aldeia mais bela é aquela onde cresceste; a mãe mais bela é a tua própria.", "fr": "Le plus beau village est celui où tu as grandi ; la plus belle mère est la tienne.", "ja": "最も美しい村はあなたが育った村、最も美しい母はあなた自身の母だ。"}},
{"id": "q114", "s": "Aşık Veysel", "t": {"tr": "Dünya bir misafirhanedir, misafir kınamaz evi.", "en": "The world is a guesthouse; a guest does not find fault with the house.", "de": "Die Welt ist ein Gasthaus; ein Gast tadelt das Haus nicht.", "es": "El mundo es una casa de huéspedes; un huésped no le pone reparos a la casa.", "pt": "O mundo é uma hospedaria; um hóspede não acha defeitos na casa.", "fr": "Le monde est une maison d'hôtes ; un hôte ne trouve pas à redire à la maison.", "ja": "世は宿屋だ。客は宿に難癖をつけない。"}},
{"id": "q115", "s": "Aşık Veysel", "t": {"tr": "Sevda dağları aşar, nehirleri geçer. Ama ilk adım ayaktan değil, gönülden atılır.", "en": "Love crosses mountains and rivers. But the first step is taken not by the foot, but by the heart.", "de": "Die Liebe überquert Berge und Flüsse. Doch den ersten Schritt tut nicht der Fuß, sondern das Herz.", "es": "El amor cruza montañas y ríos. Pero el primer paso no lo da el pie, sino el corazón.", "pt": "O amor atravessa montanhas e rios. Mas o primeiro passo não é dado pelo pé, e sim pelo coração.", "fr": "L'amour franchit montagnes et rivières. Mais le premier pas n'est pas fait par le pied, mais par le cœur.", "ja": "愛は山や川を越える。だが最初の一歩は足ではなく、心によって踏み出される。"}},
{"id": "q133", "s": "Tasavvuf Geleneği", "t": {"tr": "Mevlana sever, Şems sever, Yunus sever; çünkü aşk tek bir nehirdir.", "en": "Mevlana loves, Şems loves, Yunus loves; for love is a single river.", "de": "Mevlana liebt, Şems liebt, Yunus liebt; denn die Liebe ist ein einziger Fluss.", "es": "Mevlana ama, Şems ama, Yunus ama; pues el amor es un solo río.", "pt": "Mevlana ama, Şems ama, Yunus ama; pois o amor é um só rio.", "fr": "Mevlana aime, Şems aime, Yunus aime ; car l'amour est une seule rivière.", "ja": "メヴラーナは愛し、シェムスは愛し、ユヌスは愛する。愛はただ一筋の川なのだから。"}},
{"id": "q134", "s": "Tasavvuf Geleneği", "t": {"tr": "Nefsi öldürmeden, ruh dirileemez.", "en": "Without slaying the ego, the soul cannot come alive.", "de": "Ohne das Ego zu töten, kann die Seele nicht lebendig werden.", "es": "Sin dar muerte al ego, el alma no puede cobrar vida.", "pt": "Sem matar o ego, a alma não pode ganhar vida.", "fr": "Sans tuer l'ego, l'âme ne peut prendre vie.", "ja": "自我を殺さずに、魂は生き生きとはなれない。"}},
{"id": "q135", "s": "Tasavvuf Geleneği", "t": {"tr": "Halvette olsan da halk içinde, halkta olsan da halvette.", "en": "Be in solitude even amid the crowd, be among the crowd even in solitude.", "de": "Sei in der Einsamkeit selbst inmitten der Menge, sei unter der Menge selbst in der Einsamkeit.", "es": "Está en soledad aun en medio de la multitud, está entre la multitud aun en la soledad.", "pt": "Está na solidão mesmo no meio da multidão, está entre a multidão mesmo na solidão.", "fr": "Sois dans la solitude même au milieu de la foule, sois parmi la foule même dans la solitude.", "ja": "群衆の中にあっても孤独にあれ、孤独の中にあっても群衆の中にあれ。"}},
{"id": "q136", "s": "Tasavvuf Geleneği", "t": {"tr": "Derviş dünyaya iki eliyle sarılmaz.", "en": "A dervish does not embrace the world with both hands.", "de": "Ein Derwisch umarmt die Welt nicht mit beiden Händen.", "es": "Un derviche no abraza el mundo con ambas manos.", "pt": "Um dervixe não abraça o mundo com ambas as mãos.", "fr": "Un derviche n'embrasse pas le monde à deux mains.", "ja": "托鉢僧は両手で世界を抱きしめない。"}},
{"id": "q137", "s": "Tasavvuf Geleneği", "t": {"tr": "Sabır ile koruk helva olur.", "en": "With patience, sour grapes become sweet halva.", "de": "Mit Geduld werden saure Trauben zu süßer Halva.", "es": "Con paciencia, las uvas agrias se vuelven dulce halva.", "pt": "Com paciência, as uvas azedas tornam-se doce halva.", "fr": "Avec la patience, les raisins acides deviennent un doux halva.", "ja": "忍耐をもってすれば、酸いぶどうも甘いハルヴァになる。"}},
{"id": "q138", "s": "Tasavvuf Geleneği", "t": {"tr": "Şükür kapısını açan, bolluk içinde yaşar.", "en": "Whoever opens the door of gratitude lives in abundance.", "de": "Wer die Tür der Dankbarkeit öffnet, lebt in Fülle.", "es": "Quien abre la puerta de la gratitud vive en abundancia.", "pt": "Quem abre a porta da gratidão vive em abundância.", "fr": "Qui ouvre la porte de la gratitude vit dans l'abondance.", "ja": "感謝の扉を開く者は、豊かさの中に生きる。"}},
{"id": "q139", "s": "Tasavvuf Geleneği", "t": {"tr": "Her güzelliğin altında bir acı yatar. Her olgunluğun altında bir yara.", "en": "Beneath every beauty lies a sorrow. Beneath every ripeness, a wound.", "de": "Unter jeder Schönheit liegt ein Kummer. Unter jeder Reife eine Wunde.", "es": "Bajo cada belleza yace una pena. Bajo cada madurez, una herida.", "pt": "Sob cada beleza jaz uma tristeza. Sob cada maturidade, uma ferida.", "fr": "Sous chaque beauté repose un chagrin. Sous chaque maturité, une blessure.", "ja": "どの美の下にも悲しみが横たわる。どの円熟の下にも傷がある。"}},
{"id": "q140", "s": "Tasavvuf Geleneği", "t": {"tr": "Bülbülün gülden ayrı düşmesi gibidir insan Hakk'tan.", "en": "As the nightingale is parted from the rose, so is the human from the Truth.", "de": "Wie die Nachtigall von der Rose getrennt ist, so ist der Mensch von der Wahrheit.", "es": "Como el ruiseñor está separado de la rosa, así lo está el ser humano de la Verdad.", "pt": "Como o rouxinol está separado da rosa, assim está o ser humano da Verdade.", "fr": "Comme le rossignol est séparé de la rose, ainsi l'être humain l'est de la Vérité.", "ja": "ナイチンゲールがバラから引き離されているように、人間は真実から引き離されている。"}},
{"id": "q141", "s": "Mevlana Rumi", "t": {"tr": "Dinle, bu ney nasıl şikâyet ediyor; ayrılıkları nasıl anlatıyor.", "en": "Listen to the reed, how it tells a tale, complaining of separations.", "de": "Höre auf das Rohr, wie es eine Geschichte erzählt und über die Trennungen klagt.", "es": "Escucha a la caña, cómo cuenta una historia, lamentándose de las separaciones.", "pt": "Escuta a cana, como conta uma história, queixando-se das separações.", "fr": "Écoute le roseau, comme il raconte une histoire, se plaignant des séparations.", "ja": "葦に耳を傾けよ、いかに物語を語り、別離を嘆くかを。"}},
{"id": "q142", "s": "Mevlana Rumi", "t": {"tr": "Beni kamışlıktan kestiklerinden beri, feryadımla erkek de kadın da inledi.", "en": "Ever since they cut me from the reed bed, men and women have moaned at my lament.", "de": "Seit sie mich aus dem Röhricht schnitten, haben Männer und Frauen bei meinem Klagen geseufzt.", "es": "Desde que me cortaron del cañaveral, hombres y mujeres han gemido ante mi lamento.", "pt": "Desde que me cortaram do canavial, homens e mulheres gemeram ante o meu lamento.", "fr": "Depuis qu'on m'a coupé de la roselière, hommes et femmes ont gémi à ma plainte.", "ja": "葦原から切り取られて以来、男も女も私の嘆きにうめいてきた。"}},
{"id": "q143", "s": "Mevlana Rumi", "t": {"tr": "Ayrılıktan parça parça olmuş bir yürek isterim ki, ona özleyişin acısını anlatabileyim.", "en": "I want a heart torn to shreds by separation, that I may unfold to it the pain of longing.", "de": "Ich will ein Herz, von der Trennung zerrissen, damit ich ihm den Schmerz der Sehnsucht entfalten kann.", "es": "Quiero un corazón hecho jirones por la separación, para desplegarle el dolor de la añoranza.", "pt": "Quero um coração feito em farrapos pela separação, para lhe desdobrar a dor da saudade.", "fr": "Je veux un cœur déchiré en lambeaux par la séparation, pour lui déployer la douleur de la nostalgie.", "ja": "私は別離に引き裂かれた心が欲しい、そこに憧れの痛みを開いて見せるために。"}},
{"id": "q144", "s": "Mevlana Rumi", "t": {"tr": "Aslından uzak düşen kişi, yine birleşeceği zamanı arar durur.", "en": "Whoever is left far from their source seeks once more the time of reunion.", "de": "Wer fern von seiner Quelle blieb, sucht aufs Neue die Zeit der Wiedervereinigung.", "es": "Quien queda lejos de su origen busca de nuevo el tiempo del reencuentro.", "pt": "Quem fica longe da sua origem busca de novo o tempo do reencontro.", "fr": "Celui qui est resté loin de sa source cherche de nouveau le temps des retrouvailles.", "ja": "己の源から遠く離れた者は、再び再会のときを求める。"}},
{"id": "q145", "s": "Mevlana Rumi", "t": {"tr": "Neyin sesi havadan değil ateştendir; kimde bu ateş yoksa, yok olsun.", "en": "The reed's cry is fire, not wind; whoever lacks this fire, let them be nothing.", "de": "Der Schrei des Rohrs ist Feuer, nicht Wind; wem dieses Feuer fehlt, der sei nichts.", "es": "El llanto de la caña es fuego, no viento; quien carezca de este fuego, que sea nada.", "pt": "O choro da cana é fogo, não vento; quem não tiver este fogo, que seja nada.", "fr": "Le cri du roseau est feu, non vent ; que celui qui manque de ce feu ne soit rien.", "ja": "葦の叫びは火であり、風ではない。この火を欠く者は、無であれ。"}},
{"id": "q146", "s": "Mevlana Rumi", "t": {"tr": "Aşkın ateşidir neye düşen; aşkın coşkusudur şaraba düşen.", "en": "It is the fire of love that fell upon the reed; the ferment of love that fell upon the wine.", "de": "Es ist das Feuer der Liebe, das auf das Rohr fiel; der Rausch der Liebe, der auf den Wein fiel.", "es": "Es el fuego del amor el que cayó sobre la caña; el fermento del amor el que cayó sobre el vino.", "pt": "É o fogo do amor que caiu sobre a cana; o fermento do amor que caiu sobre o vinho.", "fr": "C'est le feu de l'amour qui est tombé sur le roseau ; le ferment de l'amour qui est tombé sur le vin.", "ja": "葦に落ちたのは愛の火、酒に落ちたのは愛の酵母だ。"}},
{"id": "q147", "s": "Mevlana Rumi", "t": {"tr": "Hamdım, piştim, yandım.", "en": "I was raw, I became cooked, I was burned.", "de": "Ich war roh, ich wurde gekocht, ich wurde verbrannt.", "es": "Era crudo, me cocí, ardí.", "pt": "Eu era cru, fiquei cozido, fui queimado.", "fr": "J'étais cru, je suis devenu cuit, j'ai été brûlé.", "ja": "私は生だった、煮えた、そして焼かれた。"}},
{"id": "q148", "s": "Mevlana Rumi", "t": {"tr": "Sevgilinin gelişiyle gönülde bir genişlik açılır; bu gönül, başka bir kapıdır.", "en": "With the Beloved's coming, a spaciousness opens in the heart; this heart is another door.", "de": "Mit dem Kommen des Geliebten öffnet sich eine Weite im Herzen; dieses Herz ist eine andere Tür.", "es": "Con la llegada del Amado se abre una amplitud en el corazón; este corazón es otra puerta.", "pt": "Com a chegada do Amado, abre-se uma amplidão no coração; este coração é outra porta.", "fr": "À la venue de l'Aimé, une ampleur s'ouvre dans le cœur ; ce cœur est une autre porte.", "ja": "愛する者の訪れとともに、心に広がりが開く。この心は、もう一つの扉だ。"}},
{"id": "q149", "s": "Mevlana Rumi", "t": {"tr": "Bu dünyaya, kalsın diye gelmedik; bir konağa indik, yine yola çıkacağız.", "en": "We did not come to this world to remain; we have lodged at an inn and will set out again.", "de": "Wir kamen nicht in diese Welt, um zu bleiben; wir haben in einer Herberge Quartier genommen und werden wieder aufbrechen.", "es": "No vinimos a este mundo para quedarnos; nos hemos hospedado en una posada y partiremos de nuevo.", "pt": "Não viemos a este mundo para ficar; hospedámo-nos numa estalagem e partiremos de novo.", "fr": "Nous ne sommes pas venus en ce monde pour rester ; nous avons logé dans une auberge et repartirons.", "ja": "私たちはとどまるためにこの世へ来たのではない。宿に泊まり、また旅立つのだ。"}},
{"id": "q150", "s": "Mevlana Rumi", "t": {"tr": "Su kabın şeklini alır; gönlün rengini içine konandan alır.", "en": "Water takes the shape of its vessel; the heart takes its color from what is placed within it.", "de": "Das Wasser nimmt die Form seines Gefäßes an; das Herz nimmt die Farbe dessen an, was man hineinlegt.", "es": "El agua toma la forma de su recipiente; el corazón toma el color de lo que se pone dentro.", "pt": "A água toma a forma do seu recipiente; o coração toma a cor daquilo que se coloca dentro.", "fr": "L'eau prend la forme de son récipient ; le cœur prend la couleur de ce qu'on y dépose.", "ja": "水は器の形をとる。心はそこに置かれたものの色をとる。"}},
{"id": "q151", "s": "Mevlana Rumi", "t": {"tr": "Bağ bozulunca üzüm şaraba dönüşür; sen de dağıl ki başka bir şeye dönüşesin.", "en": "When the vineyard is undone the grape becomes wine; you too must come apart, that you may become something else.", "de": "Wenn der Weinberg vergeht, wird die Traube zu Wein; auch du musst zerfallen, damit du etwas anderes wirst.", "es": "Cuando el viñedo se deshace, la uva se vuelve vino; tú también debes deshacerte para volverte otra cosa.", "pt": "Quando o vinhedo se desfaz, a uva torna-se vinho; tu também deves desfazer-te, para te tornares outra coisa.", "fr": "Quand la vigne se défait, le raisin devient vin ; toi aussi tu dois te défaire, pour devenir autre chose.", "ja": "ぶどう畑が解けるとき、ぶどうは酒となる。あなたもまた、ほどけてこそ、別のものになれる。"}},
{"id": "q152", "s": "Mevlana Rumi", "t": {"tr": "Sen düşünceden ibaretsin; gerisi et ile kemiktir. Gül düşünürsen gül bahçesi olursun, diken düşünürsen dikenlik.", "en": "You are nothing but thought, brother; the rest is bone and sinew. Think a rose and you are a rose garden; think a thorn and you are thorn brush.", "de": "Du bist nichts als Gedanke, Bruder; der Rest ist Knochen und Sehne. Denk eine Rose, und du bist ein Rosengarten; denk einen Dorn, und du bist Dorngestrüpp.", "es": "No eres más que pensamiento, hermano; el resto es hueso y tendón. Piensa una rosa y eres un jardín de rosas; piensa una espina y eres un zarzal.", "pt": "Não és senão pensamento, irmão; o resto é osso e tendão. Pensa uma rosa e és um roseiral; pensa um espinho e és um espinheiro.", "fr": "Tu n'es rien que pensée, mon frère ; le reste est os et tendon. Pense une rose et tu es un jardin de roses ; pense une épine et tu es un buisson d'épines.", "ja": "兄弟よ、あなたは思いにほかならぬ。残りは骨と腱だ。バラを思えばバラ園となり、棘を思えば棘の茂みとなる。"}},
{"id": "q153", "s": "Mevlana Rumi", "t": {"tr": "Dünün geçti, sözü de onunla gitti; bugün yeni bir söz söylemek gerek.", "en": "Yesterday has passed, and its words passed with it; today one must speak a new word.", "de": "Gestern ist vergangen, und mit ihm seine Worte; heute muss man ein neues Wort sprechen.", "es": "El ayer ha pasado, y con él pasaron sus palabras; hoy hay que decir una palabra nueva.", "pt": "O ontem passou, e com ele passaram as suas palavras; hoje é preciso dizer uma palavra nova.", "fr": "Hier est passé, et ses paroles avec lui ; aujourd'hui il faut dire une parole nouvelle.", "ja": "昨日は過ぎ、その言葉も過ぎ去った。今日は新しい言葉を語らねばならぬ。"}},
{"id": "q154", "s": "Mevlana Rumi", "t": {"tr": "Dün geçti, dünkü sözler de geçti; şimdi yeni şeyler söylemek gerek.", "en": "Yesterday is gone, and yesterday's talk is gone; now it is time to speak of new things.", "de": "Das Gestern ist fort, und das Gerede von gestern ist fort; nun ist es Zeit, von Neuem zu sprechen.", "es": "El ayer se ha ido, y la charla de ayer se ha ido; ahora es tiempo de hablar de cosas nuevas.", "pt": "O ontem foi-se, e a conversa de ontem foi-se; agora é tempo de falar de coisas novas.", "fr": "Hier s'en est allé, et les propos d'hier s'en sont allés ; il est temps maintenant de parler de choses nouvelles.", "ja": "昨日は去り、昨日の話も去った。今は新しいことを語るときだ。"}},
{"id": "q155", "s": "Mevlana Rumi", "t": {"tr": "Kuyunun dibinde gibiyiz; ipi salan, bizi yukarı çekendir. İpi salan ele güven.", "en": "We are as if at the bottom of a well; the One who lets down the rope is the One who draws us up. Trust the hand that lowers the rope.", "de": "Wir sind wie am Grund eines Brunnens; der das Seil hinablässt, ist der, der uns heraufzieht. Vertraue der Hand, die das Seil senkt.", "es": "Somos como si estuviéramos en el fondo de un pozo; quien arroja la cuerda es quien nos saca. Confía en la mano que baja la cuerda.", "pt": "Somos como que no fundo de um poço; quem desce a corda é quem nos puxa para cima. Confia na mão que baixa a corda.", "fr": "Nous sommes comme au fond d'un puits ; celui qui descend la corde est celui qui nous remonte. Fais confiance à la main qui abaisse la corde.", "ja": "私たちは井戸の底にいるかのようだ。綱を下ろす者こそ、私たちを引き上げる者。綱を下ろす手を信じよ。"}},
{"id": "q156", "s": "Mevlana Rumi", "t": {"tr": "Bir bahçeye girersen, dikenleri değil gülleri gör; gülü görenin gönlü gül olur.", "en": "If you enter a garden, see the roses, not the thorns; whoever beholds the rose, their heart becomes a rose.", "de": "Trittst du in einen Garten, sieh die Rosen, nicht die Dornen; wer die Rose schaut, dessen Herz wird zur Rose.", "es": "Si entras en un jardín, mira las rosas, no las espinas; quien contempla la rosa, su corazón se vuelve rosa.", "pt": "Se entrares num jardim, vê as rosas, não os espinhos; quem contempla a rosa, o seu coração torna-se rosa.", "fr": "Si tu entres dans un jardin, vois les roses, non les épines ; qui contemple la rose, son cœur devient rose.", "ja": "庭に入るなら、棘ではなくバラを見よ。バラを見つめる者の心は、バラとなる。"}},
{"id": "q157", "s": "Mevlana Rumi", "t": {"tr": "Kötülüğe iyilikle karşılık ver; çünkü kötülük dumandır, iyilik ışıktır.", "en": "Answer evil with good; for evil is smoke and good is light.", "de": "Begegne dem Bösen mit Gutem; denn das Böse ist Rauch und das Gute ist Licht.", "es": "Responde al mal con el bien; pues el mal es humo y el bien es luz.", "pt": "Responde ao mal com o bem; pois o mal é fumo e o bem é luz.", "fr": "Réponds au mal par le bien ; car le mal est fumée et le bien est lumière.", "ja": "悪には善で応えよ。悪は煙、善は光なのだから。"}},
{"id": "q158", "s": "Mevlana Rumi", "t": {"tr": "Sabret; çünkü sabır, sıkıntıdan ferahlığa açılan anahtardır.", "en": "Be patient; for patience is the key that opens relief from distress.", "de": "Sei geduldig; denn die Geduld ist der Schlüssel, der die Erleichterung aus der Not öffnet.", "es": "Sé paciente; pues la paciencia es la llave que abre el alivio en la angustia.", "pt": "Sê paciente; pois a paciência é a chave que abre o alívio na aflição.", "fr": "Sois patient ; car la patience est la clé qui ouvre le soulagement dans la détresse.", "ja": "忍耐せよ。忍耐は苦難からの安らぎを開く鍵なのだから。"}},
{"id": "q159", "s": "Mevlana Rumi", "t": {"tr": "Tövbe atına bin; bu at, bir anda uzun yolları aşar.", "en": "Mount the steed of repentance; this steed crosses long roads in a single moment.", "de": "Besteige das Ross der Reue; dieses Ross durchquert lange Wege in einem einzigen Augenblick.", "es": "Monta el corcel del arrepentimiento; este corcel cruza largos caminos en un solo instante.", "pt": "Monta o corcel do arrependimento; este corcel atravessa longos caminhos num único instante.", "fr": "Monte le coursier du repentir ; ce coursier franchit de longs chemins en un seul instant.", "ja": "悔悟の駿馬に乗れ。この馬は、ただ一瞬で長い道を駆け抜ける。"}},
{"id": "q161", "s": "Mevlana Rumi", "t": {"tr": "Aşk öyle bir denizdir ki, göğün üstünü köpük kaplamıştır.", "en": "Love is such a sea that its foam has covered even the face of the heavens.", "de": "Die Liebe ist ein solches Meer, dass ihr Schaum selbst das Antlitz der Himmel bedeckt hat.", "es": "El amor es un mar tan grande que su espuma ha cubierto hasta el rostro de los cielos.", "pt": "O amor é um mar tão grande que a sua espuma cobriu até a face dos céus.", "fr": "L'amour est une mer telle que son écume a couvert jusqu'au visage des cieux.", "ja": "愛はその泡が天の顔さえ覆うほどの海だ。"}},
{"id": "q162", "s": "Mevlana Rumi", "t": {"tr": "Aşk, ağır yükleri hafifletir; aşkla her acı tatlı olur.", "en": "Love makes heavy burdens light; with love every pain turns sweet.", "de": "Die Liebe macht schwere Lasten leicht; mit der Liebe wird jeder Schmerz süß.", "es": "El amor hace ligeras las cargas pesadas; con amor todo dolor se vuelve dulce.", "pt": "O amor torna leves os fardos pesados; com amor toda dor se torna doce.", "fr": "L'amour rend légers les lourds fardeaux ; avec l'amour toute douleur devient douce.", "ja": "愛は重い荷を軽くする。愛とともに、どんな痛みも甘くなる。"}},
{"id": "q163", "s": "Mevlana Rumi", "t": {"tr": "Akıl topal eşek üstündeki yolcu gibidir; aşk ise kanatla uçar.", "en": "Reason is like a traveler upon a lame donkey; love, by contrast, flies upon wings.", "de": "Der Verstand ist wie ein Reisender auf einem lahmen Esel; die Liebe dagegen fliegt auf Flügeln.", "es": "La razón es como un viajero sobre un asno cojo; el amor, en cambio, vuela sobre alas.", "pt": "A razão é como um viajante sobre um burro coxo; o amor, ao contrário, voa sobre asas.", "fr": "La raison est comme un voyageur sur un âne boiteux ; l'amour, au contraire, vole sur des ailes.", "ja": "理性は足の不自由なロバに乗る旅人のようだ。一方、愛は翼で飛ぶ。"}},
{"id": "q164", "s": "Mevlana Rumi", "t": {"tr": "Cüzler küllerine doğru çekilir; biz de aslımıza, sevgiliye doğru çekiliriz.", "en": "The parts are drawn toward their wholes; so are we drawn toward our origin, toward the Beloved.", "de": "Die Teile werden zu ihren Ganzen gezogen; so werden auch wir zu unserem Ursprung gezogen, zum Geliebten.", "es": "Las partes son atraídas hacia sus todos; así somos atraídos hacia nuestro origen, hacia el Amado.", "pt": "As partes são atraídas para os seus todos; assim somos atraídos para a nossa origem, para o Amado.", "fr": "Les parties sont attirées vers leurs touts ; ainsi sommes-nous attirés vers notre origine, vers l'Aimé.", "ja": "部分はその全体へと引き寄せられる。そのように私たちも己の源へ、愛する者へと引き寄せられる。"}},
{"id": "q165", "s": "Mevlana Rumi", "t": {"tr": "Damla, denize ulaşınca deniz olur; sen de benliğini bırak ki ummana karışasın.", "en": "When the drop reaches the sea it becomes the sea; you too must let go of your self, that you may merge with the ocean.", "de": "Wenn der Tropfen das Meer erreicht, wird er zum Meer; auch du musst dein Selbst loslassen, damit du mit dem Ozean verschmilzt.", "es": "Cuando la gota llega al mar se vuelve mar; tú también debes soltar tu yo para fundirte con el océano.", "pt": "Quando a gota chega ao mar torna-se mar; tu também deves soltar o teu eu, para te fundires com o oceano.", "fr": "Quand la goutte atteint la mer, elle devient la mer ; toi aussi tu dois lâcher ton soi, pour te fondre dans l'océan.", "ja": "雫が海に達すれば海となる。あなたもまた己を手放してこそ、大海と一つになれる。"}},
{"id": "q166", "s": "Mevlana Rumi", "t": {"tr": "İnsan iki dünya arasında bir köprüdür; üzerinde durma, geç.", "en": "The human being is a bridge between two worlds; do not linger upon it, pass over.", "de": "Der Mensch ist eine Brücke zwischen zwei Welten; verweile nicht auf ihr, geh hinüber.", "es": "El ser humano es un puente entre dos mundos; no te demores en él, pasa al otro lado.", "pt": "O ser humano é uma ponte entre dois mundos; não te demores nela, passa para o outro lado.", "fr": "L'être humain est un pont entre deux mondes ; ne t'attarde pas dessus, passe de l'autre côté.", "ja": "人間は二つの世界を結ぶ橋だ。その上にとどまるな、渡り越えよ。"}},
{"id": "q167", "s": "Mevlana Rumi", "t": {"tr": "Yol gösteren ışık içeridedir; dışarıda mum arayan, kendi güneşini söndürmüş demektir.", "en": "The guiding light is within; whoever seeks a candle outside has put out their own sun.", "de": "Das führende Licht ist innen; wer draußen eine Kerze sucht, hat seine eigene Sonne ausgelöscht.", "es": "La luz que guía está dentro; quien busca una vela afuera ha apagado su propio sol.", "pt": "A luz que guia está dentro; quem procura uma vela lá fora apagou o seu próprio sol.", "fr": "La lumière qui guide est au-dedans ; qui cherche une bougie au-dehors a éteint son propre soleil.", "ja": "導きの光は内にある。外にろうそくを求める者は、己の太陽を消したのだ。"}},
{"id": "q168", "s": "Mevlana Rumi", "t": {"tr": "Cömert ol; çünkü toprak, tohumu cömertçe alır ve kat kat geri verir.", "en": "Be generous; for the earth receives the seed generously and returns it manifold.", "de": "Sei großzügig; denn die Erde empfängt den Samen großzügig und gibt ihn vielfach zurück.", "es": "Sé generoso; pues la tierra recibe la semilla con generosidad y la devuelve multiplicada.", "pt": "Sê generoso; pois a terra recebe a semente com generosidade e devolve-a multiplicada.", "fr": "Sois généreux ; car la terre reçoit la graine avec générosité et la rend au centuple.", "ja": "寛大であれ。大地は種を寛大に受け、幾倍にもして返すのだから。"}},
{"id": "q169", "s": "Mevlana Rumi", "t": {"tr": "Veren el, alan elden üstündür; vererek azalmazsın, çoğalırsın.", "en": "The giving hand is above the receiving hand; by giving you do not grow less, you grow more.", "de": "Die gebende Hand steht über der nehmenden; durch Geben wirst du nicht weniger, du wirst mehr.", "es": "La mano que da está por encima de la que recibe; al dar no menguas, creces.", "pt": "A mão que dá está acima da que recebe; ao dar não diminuis, cresces.", "fr": "La main qui donne est au-dessus de celle qui reçoit ; en donnant tu ne deviens pas moindre, tu deviens plus grand.", "ja": "与える手は受け取る手の上にある。与えても減るのではなく、増えるのだ。"}},
{"id": "q170", "s": "Mevlana Rumi", "t": {"tr": "Şükret; çünkü şükür, nimetin bağıdır, onu sana bağlar.", "en": "Give thanks; for gratitude is the tether of blessing, binding it to you.", "de": "Sei dankbar; denn die Dankbarkeit ist das Band des Segens, das ihn an dich bindet.", "es": "Da gracias; pues la gratitud es la atadura de la bendición, que la liga a ti.", "pt": "Dá graças; pois a gratidão é a amarra da bênção, que a prende a ti.", "fr": "Rends grâce ; car la gratitude est l'attache de la bénédiction, qui la lie à toi.", "ja": "感謝せよ。感謝は恵みをあなたに結びつける綱なのだから。"}},
{"id": "q171", "s": "Mevlana Rumi", "t": {"tr": "Her sabah yeniden doğarız; dünkü kaygıları yatağında bırak.", "en": "Each morning we are born anew; leave yesterday's worries in their bed.", "de": "Jeden Morgen werden wir neu geboren; lass die Sorgen von gestern in ihrem Bett.", "es": "Cada mañana nacemos de nuevo; deja las preocupaciones de ayer en su lecho.", "pt": "A cada manhã nascemos de novo; deixa as preocupações de ontem no seu leito.", "fr": "Chaque matin nous naissons à nouveau ; laisse les soucis d'hier dans leur lit.", "ja": "毎朝、私たちは新たに生まれる。昨日の憂いはその寝床に置いておけ。"}},
{"id": "q172", "s": "Mevlana Rumi", "t": {"tr": "Gönül aynasını cilala; pas tutmuş ayna, ne sureti gösterir ne nuru.", "en": "Polish the mirror of the heart; a rusted mirror shows neither form nor light.", "de": "Poliere den Spiegel des Herzens; ein verrosteter Spiegel zeigt weder Gestalt noch Licht.", "es": "Pule el espejo del corazón; un espejo oxidado no muestra ni forma ni luz.", "pt": "Pole o espelho do coração; um espelho enferrujado não mostra nem forma nem luz.", "fr": "Polis le miroir du cœur ; un miroir rouillé ne montre ni forme ni lumière.", "ja": "心の鏡を磨け。錆びた鏡は、姿も光も映さない。"}},
{"id": "q173", "s": "Mevlana Rumi", "t": {"tr": "Nefis, beslendikçe azar; aç bıraktıkça uysallaşır.", "en": "The ego grows insolent the more it is fed; the more you starve it, the gentler it becomes.", "de": "Das Ego wird umso anmaßender, je mehr man es füttert; je mehr du es hungern lässt, desto sanfter wird es.", "es": "El ego se vuelve más insolente cuanto más se le alimenta; cuanto más lo dejas en ayunas, más manso se vuelve.", "pt": "O ego torna-se mais insolente quanto mais o alimentas; quanto mais o deixas em jejum, mais manso se torna.", "fr": "L'ego devient d'autant plus insolent qu'on le nourrit ; plus tu l'affames, plus il devient doux.", "ja": "自我は養えば養うほど傲慢になる。飢えさせるほど、穏やかになる。"}},
{"id": "q174", "s": "Mevlana Rumi", "t": {"tr": "Kendini arayan, sonunda kendinden geçmeyi öğrenir.", "en": "Whoever searches for the self in the end learns to pass beyond the self.", "de": "Wer nach dem Selbst sucht, lernt am Ende, über das Selbst hinauszugehen.", "es": "Quien busca el yo aprende al fin a ir más allá del yo.", "pt": "Quem procura o eu aprende, ao fim, a ir além do eu.", "fr": "Qui cherche le soi apprend à la fin à dépasser le soi.", "ja": "自己を探す者は、ついには自己を越えていくことを学ぶ。"}},
{"id": "q175", "s": "Mevlana Rumi", "t": {"tr": "Ölümümün ardından mezarımı yerde arama; o, âriflerin gönlündedir.", "en": "After my death, do not seek my grave in the ground; it is in the hearts of those who know.", "de": "Such nach meinem Tod mein Grab nicht in der Erde; es ist in den Herzen derer, die wissen.", "es": "Después de mi muerte, no busques mi tumba en la tierra; está en los corazones de quienes saben.", "pt": "Depois da minha morte, não procures o meu túmulo na terra; está nos corações dos que sabem.", "fr": "Après ma mort, ne cherche pas ma tombe dans la terre ; elle est dans les cœurs de ceux qui savent.", "ja": "私の死後、地中に私の墓を探すな。それは知る者たちの心の中にある。"}},
{"id": "q176", "s": "Mevlana Rumi", "t": {"tr": "Bizim ölümümüz düğün gecemizdir; çünkü ayrılık biter, kavuşma başlar.", "en": "Our death is our wedding night; for separation ends and reunion begins.", "de": "Unser Tod ist unsere Hochzeitsnacht; denn die Trennung endet und die Wiedervereinigung beginnt.", "es": "Nuestra muerte es nuestra noche de bodas; pues la separación termina y comienza el reencuentro.", "pt": "A nossa morte é a nossa noite de núpcias; pois a separação termina e o reencontro começa.", "fr": "Notre mort est notre nuit de noces ; car la séparation finit et les retrouvailles commencent.", "ja": "私たちの死は、私たちの婚礼の夜だ。別離が終わり、再会が始まるのだから。"}},
{"id": "q177", "s": "Mevlana Rumi", "t": {"tr": "Dost, gönlün hekimidir; derdini ondan saklama.", "en": "A friend is the physician of the heart; do not hide your sorrow from them.", "de": "Ein Freund ist der Arzt des Herzens; verbirg deinen Kummer nicht vor ihm.", "es": "Un amigo es el médico del corazón; no le ocultes tu pena.", "pt": "Um amigo é o médico do coração; não lhe escondas a tua tristeza.", "fr": "Un ami est le médecin du cœur ; ne lui cache pas ton chagrin.", "ja": "友は心の医者だ。あなたの悲しみを彼から隠すな。"}},
{"id": "q178", "s": "Mevlana Rumi", "t": {"tr": "Sözün gümüşse, susman altındır; ama yerinde söz, inci gibidir.", "en": "If your speech is silver, your silence is gold; yet a word in its proper place is like a pearl.", "de": "Ist deine Rede Silber, so ist dein Schweigen Gold; doch ein Wort am rechten Ort ist wie eine Perle.", "es": "Si tu palabra es plata, tu silencio es oro; pero una palabra en su justo lugar es como una perla.", "pt": "Se a tua fala é prata, o teu silêncio é ouro; mas uma palavra no seu devido lugar é como uma pérola.", "fr": "Si ta parole est d'argent, ton silence est d'or ; mais un mot à sa juste place est comme une perle.", "ja": "あなたの言葉が銀なら、沈黙は金だ。だが、ふさわしい場所に置かれた一言は真珠のようだ。"}},
{"id": "q179", "s": "Mevlana Rumi", "t": {"tr": "Korkma; sana ulaşması gereken şey, başkasına gitmez.", "en": "Do not fear; what is meant to reach you will not go to another.", "de": "Fürchte dich nicht; was dich erreichen soll, geht nicht zu einem anderen.", "es": "No temas; lo que ha de llegarte no irá a otro.", "pt": "Não temas; o que te há de chegar não irá para outro.", "fr": "Ne crains pas ; ce qui doit te parvenir n'ira pas à un autre.", "ja": "恐れるな。あなたに届くべきものは、他の者のところへは行かない。"}},
{"id": "q180", "s": "Mevlana Rumi", "t": {"tr": "Hak, kalpleri sınar; sabredenin kalbi altın gibi parlar çıkar.", "en": "The Truth tests hearts; the heart of the patient one comes forth shining like gold.", "de": "Die Wahrheit prüft die Herzen; das Herz des Geduldigen geht hervor und glänzt wie Gold.", "es": "La Verdad pone a prueba los corazones; el corazón del paciente sale reluciente como el oro.", "pt": "A Verdade põe os corações à prova; o coração do paciente sai reluzente como o ouro.", "fr": "La Vérité éprouve les cœurs ; le cœur du patient en ressort brillant comme l'or.", "ja": "真実は心を試す。忍耐する者の心は、金のように輝いて現れる。"}},
{"id": "q181", "s": "Mevlana Rumi", "t": {"tr": "Aşk davası kolay söylenir; ama onun kanıtı, çekilen cefada belli olur.", "en": "The claim of love is easily spoken; but its proof appears in the hardship one endures.", "de": "Den Anspruch auf Liebe spricht man leicht aus; doch ihr Beweis zeigt sich in der Härte, die man erträgt.", "es": "La pretensión del amor se dice con facilidad; pero su prueba aparece en la dureza que uno soporta.", "pt": "A pretensão do amor diz-se com facilidade; mas a sua prova aparece na dureza que se suporta.", "fr": "Prétendre à l'amour se dit aisément ; mais sa preuve apparaît dans l'épreuve que l'on endure.", "ja": "愛を主張することはたやすい。だがその証は、耐え忍ぶ苦難の中に現れる。"}},
{"id": "q182", "s": "Mevlana Rumi", "t": {"tr": "Susuzluk suyu arar; ama su da susuzları arar.", "en": "Not only does the thirsty seek the water; the water too, unseen, seeks the thirsty.", "de": "Nicht nur der Durstige sucht das Wasser; auch das Wasser sucht, ungesehen, den Durstigen.", "es": "No solo el sediento busca el agua; el agua también, sin que se vea, busca al sediento.", "pt": "Não só o sedento procura a água; a água também, sem que se veja, procura o sedento.", "fr": "Non seulement l'assoiffé cherche l'eau ; l'eau aussi, invisible, cherche l'assoiffé.", "ja": "渇いた者が水を求めるだけではない。水もまた、見えぬところで渇いた者を求めている。"}},
{"id": "q183", "s": "Mevlana Rumi", "t": {"tr": "Bir kapı kapanır, başkası açılır; karanlığa değil açılan kapıya bak.", "en": "One door closes, another opens; look not at the darkness but at the opening door.", "de": "Eine Tür schließt sich, eine andere öffnet sich; schau nicht auf das Dunkel, sondern auf die sich öffnende Tür.", "es": "Una puerta se cierra, otra se abre; no mires la oscuridad, sino la puerta que se abre.", "pt": "Uma porta fecha-se, outra abre-se; não olhes para a escuridão, mas para a porta que se abre.", "fr": "Une porte se ferme, une autre s'ouvre ; ne regarde pas l'obscurité mais la porte qui s'ouvre.", "ja": "一つの扉が閉じれば、もう一つが開く。闇ではなく、開きゆく扉を見よ。"}},
{"id": "q184", "s": "Mevlana Rumi", "t": {"tr": "Geceyi suçlama; yıldızlar ancak karanlıkta görünür.", "en": "Do not blame the night; the stars become visible only in the dark.", "de": "Tadle nicht die Nacht; die Sterne werden nur im Dunkel sichtbar.", "es": "No culpes a la noche; las estrellas solo se hacen visibles en lo oscuro.", "pt": "Não culpes a noite; as estrelas só se tornam visíveis no escuro.", "fr": "Ne blâme pas la nuit ; les étoiles ne deviennent visibles que dans l'obscurité.", "ja": "夜を責めるな。星は闇の中でこそ見えるようになる。"}},
{"id": "q196", "s": "Aşık Veysel", "t": {"tr": "Güzelliğin on par'etmez, bu bendeki aşk olmasa.", "en": "Your beauty would be worth nothing, were it not for this love in me.", "de": "Your beauty would be worth nothing, were it not for this love in me.", "es": "Your beauty would be worth nothing, were it not for this love in me.", "pt": "Your beauty would be worth nothing, were it not for this love in me.", "fr": "Your beauty would be worth nothing, were it not for this love in me.", "ja": "Your beauty would be worth nothing, were it not for this love in me."}},
{"id": "n503", "s": "Marcus Aurelius", "t": {"tr": "Engel yolun kendisi olur. Yolunu kapatan şey, yürüyeceğin yeni yolu gösterir.", "en": "The obstacle becomes the way. What blocks your path shows you the path you are meant to walk.", "de": "Das Hindernis wird zum Weg. Was dir den Weg versperrt, zeigt dir den Weg, den du gehen sollst.", "es": "El obstáculo se convierte en el camino. Lo que bloquea tu paso te muestra el camino que debes andar.", "pt": "O obstáculo torna-se o caminho. O que bloqueia a tua passagem mostra-te o caminho que deves andar.", "fr": "L'obstacle devient le chemin. Ce qui barre ta route te montre la route que tu dois prendre.", "ja": "障害こそが道となる。行く手を塞ぐものが、あなたの歩むべき新しい道を示している。"}},
{"id": "n504", "s": "Epiktetos", "t": {"tr": "Bazı şeyler bize bağlıdır, bazıları değil. Huzur, bu ikisini birbirine karıştırmayı bıraktığın gün başlar.", "en": "Some things are within our power, others are not. Peace begins the day you stop confusing the two.", "de": "Manches steht in unserer Macht, anderes nicht. Der Frieden beginnt an dem Tag, an dem du aufhörst, beides zu verwechseln.", "es": "Algunas cosas dependen de nosotros, otras no. La paz empieza el día en que dejas de confundirlas.", "pt": "Algumas coisas dependem de nós, outras não. A paz começa no dia em que deixas de confundir as duas.", "fr": "Certaines choses dépendent de nous, d'autres non. La paix commence le jour où tu cesses de confondre les deux.", "ja": "あることは我々の力の内にあり、あることはそうではない。平安は、その二つを取り違えるのをやめた日に始まる。"}},
{"id": "n505", "s": "Epiktetos", "t": {"tr": "İnsanları rahatsız eden şeyler değil, şeyler hakkındaki düşünceleridir.", "en": "People are disturbed not by things, but by the views they take of them.", "de": "Nicht die Dinge beunruhigen die Menschen, sondern ihre Meinungen über die Dinge.", "es": "No son las cosas las que perturban a las personas, sino las opiniones que tienen sobre ellas.", "pt": "Não são as coisas que perturbam as pessoas, mas as opiniões que têm delas.", "fr": "Ce ne sont pas les choses qui troublent les hommes, mais les jugements qu'ils portent sur elles.", "ja": "人を乱すのは物事そのものではなく、物事についての考えである。"}},
{"id": "n506", "s": "Seneca", "t": {"tr": "Gerçekte acı çektiğimizden çok, hayalimizde acı çekeriz.", "en": "We suffer more in imagination than in reality.", "de": "Wir leiden mehr in der Einbildung als in der Wirklichkeit.", "es": "Sufrimos más en la imaginación que en la realidad.", "pt": "Sofremos mais na imaginação do que na realidade.", "fr": "Nous souffrons plus dans l'imagination que dans la réalité.", "ja": "私たちは現実よりも想像の中でより多く苦しむ。"}},
{"id": "n507", "s": "Seneca", "t": {"tr": "Hiçbir rüzgâr, hangi limana gideceğini bilmeyen gemiye yardım etmez.", "en": "No wind favors the ship that does not know which harbor it seeks.", "de": "Kein Wind hilft dem Schiff, das seinen Hafen nicht kennt.", "es": "Ningún viento ayuda al barco que no sabe a qué puerto va.", "pt": "Nenhum vento ajuda o navio que não sabe para que porto vai.", "fr": "Aucun vent n'est favorable au navire qui ne sait vers quel port il va.", "ja": "どの港を目指すか知らない船には、どんな風も味方しない。"}},
{"id": "n508", "s": "Buddha", "t": {"tr": "Zihin her şeyin öncüsüdür. Ne düşünürsen o olursun. Saf bir zihinle konuş ya da davran; mutluluk seni gölgen gibi izler.", "en": "Mind precedes all things. What you think, you become. Speak or act with a clear mind, and happiness follows you like your shadow.", "de": "Der Geist geht allem voran. Was du denkst, das wirst du. Sprich oder handle mit klarem Geist, und das Glück folgt dir wie dein Schatten.", "es": "La mente precede a todas las cosas. Lo que piensas, en eso te conviertes. Habla o actúa con la mente clara y la dicha te seguirá como tu sombra.", "pt": "A mente precede todas as coisas. Aquilo que pensas, isso te tornas. Fala ou age com a mente clara e a felicidade seguir-te-á como a tua sombra.", "fr": "L'esprit précède toute chose. Ce que tu penses, tu le deviens. Parle ou agis avec un esprit clair, et le bonheur te suivra comme ton ombre.", "ja": "心はすべてに先立つ。思うものに人はなる。澄んだ心で語り、行いなさい。幸いは影のようについてくる。"}},
{"id": "n509", "s": "Buddha", "t": {"tr": "Geçmişte oyalanma, geleceği hayal etme. Zihni şimdiki ana topla.", "en": "Do not dwell in the past, do not dream of the future. Gather the mind into the present moment.", "de": "Verweile nicht in der Vergangenheit, träume nicht von der Zukunft. Sammle den Geist im gegenwärtigen Augenblick.", "es": "No habites en el pasado, no sueñes con el futuro. Recoge la mente en el momento presente.", "pt": "Não habites no passado, não sonhes com o futuro. Recolhe a mente no momento presente.", "fr": "Ne demeure pas dans le passé, ne rêve pas de l'avenir. Rassemble l'esprit dans l'instant présent.", "ja": "過去にとどまるな、未来を夢見るな。心を今この瞬間に集めよ。"}},
{"id": "n510", "s": "Buddha", "t": {"tr": "Öfkeye tutunmak, birine fırlatmak niyetiyle kızgın bir kömürü avucunda tutmaya benzer. Yanan sensin.", "en": "Holding on to anger is like grasping a hot coal to throw at someone. You are the one who gets burned.", "de": "An Zorn festzuhalten ist, wie eine glühende Kohle zu halten, um sie auf jemanden zu werfen. Verbrannt wirst du.", "es": "Aferrarse a la ira es como sostener un carbón ardiente para arrojarlo a alguien. El que se quema eres tú.", "pt": "Agarrar-se à raiva é como segurar um carvão em brasa para o atirar a alguém. Quem se queima és tu.", "fr": "S'accrocher à la colère, c'est tenir un charbon ardent pour le jeter sur quelqu'un. Celui qui brûle, c'est toi.", "ja": "怒りを抱えることは、誰かに投げつけようと熱い炭を握るようなものだ。焼かれるのはあなた自身である。"}},
{"id": "n511", "s": "Dhammapada", "t": {"tr": "Nefret nefretle dinmez; ancak sevgiyle diner. Bu değişmez bir yasadır.", "en": "Hatred is never ended by hatred, but by love alone. This is an unchanging law.", "de": "Hass wird niemals durch Hass beendet, sondern allein durch Liebe. Das ist ein unwandelbares Gesetz.", "es": "El odio nunca termina con odio, sino solo con amor. Esta es una ley inmutable.", "pt": "O ódio nunca se apaga com ódio, mas apenas com amor. Esta é uma lei imutável.", "fr": "La haine ne s'éteint jamais par la haine, mais par l'amour seul. C'est une loi immuable.", "ja": "憎しみは憎しみによって終わらない。ただ愛によってのみ終わる。これは変わることのない法である。"}},
{"id": "n512", "s": "Zen Geleneği", "t": {"tr": "Aydınlanmadan önce: odun kes, su taşı. Aydınlandıktan sonra: odun kes, su taşı.", "en": "Before enlightenment: chop wood, carry water. After enlightenment: chop wood, carry water.", "de": "Vor der Erleuchtung: Holz hacken, Wasser tragen. Nach der Erleuchtung: Holz hacken, Wasser tragen.", "es": "Antes de la iluminación: corta leña, acarrea agua. Después de la iluminación: corta leña, acarrea agua.", "pt": "Antes da iluminação: corta lenha, carrega água. Depois da iluminação: corta lenha, carrega água.", "fr": "Avant l'éveil: coupe du bois, porte de l'eau. Après l'éveil: coupe du bois, porte de l'eau.", "ja": "悟る前は、薪を割り、水を汲む。悟った後も、薪を割り、水を汲む。"}},
{"id": "n513", "s": "Laozi", "t": {"tr": "Suyun yumuşaklığı taşın sertliğini yener. Yumuşak olan, sert olanı aşındırır; boyun eğen, kırılmaz.", "en": "Water is soft yet wears down stone. What yields outlasts what resists; what bends does not break.", "de": "Wasser ist weich und höhlt doch den Stein. Was nachgibt, überdauert das Harte; was sich beugt, bricht nicht.", "es": "El agua es blanda y sin embargo desgasta la piedra. Lo que cede sobrevive a lo que resiste; lo que se dobla no se rompe.", "pt": "A água é branda e no entanto desgasta a pedra. O que cede dura mais do que o que resiste; o que verga não quebra.", "fr": "L'eau est douce et pourtant elle use la pierre. Ce qui cède dure plus que ce qui résiste; ce qui plie ne rompt pas.", "ja": "水は柔らかいが石を穿つ。譲るものは抗うものより長く残り、しなうものは折れない。"}},
{"id": "n514", "s": "Laozi", "t": {"tr": "Çamurlu suyu durulmaya bırak. Sabredebilir misin, çamur çöküp su kendiliğinden berraklaşana kadar?", "en": "Let muddy water settle. Can you wait until the silt sinks and the water clears by itself?", "de": "Lass das trübe Wasser sich setzen. Kannst du warten, bis der Schlamm sinkt und das Wasser von selbst klar wird?", "es": "Deja que el agua turbia se asiente. ¿Puedes esperar a que el lodo baje y el agua se aclare por sí sola?", "pt": "Deixa a água turva assentar. Consegues esperar até que o lodo desça e a água clareie por si mesma?", "fr": "Laisse l'eau trouble se déposer. Peux-tu attendre que la vase descende et que l'eau s'éclaircisse d'elle-même?", "ja": "濁った水は静かに置いておきなさい。泥が沈み、水がひとりでに澄むまで待てるだろうか。"}},
{"id": "n515", "s": "Laozi", "t": {"tr": "Tekerleği tekerlek yapan göbeğindeki boşluktur. Kabı kap yapan içindeki boşluktur. Odayı oda yapan kapı ve pencerelerinin boşluğudur.", "en": "The hub makes the wheel because it is empty. The vessel is useful because it is hollow. The room is livable because of the space in its doors and windows.", "de": "Die Nabe macht das Rad, weil sie leer ist. Das Gefäß nützt, weil es hohl ist. Der Raum ist bewohnbar durch die Leere seiner Türen und Fenster.", "es": "El cubo hace la rueda porque está vacío. La vasija sirve porque es hueca. La habitación se habita gracias al vacío de sus puertas y ventanas.", "pt": "O cubo faz a roda porque está vazio. A vasilha serve porque é oca. O quarto habita-se graças ao vazio das suas portas e janelas.", "fr": "Le moyeu fait la roue parce qu'il est vide. Le vase sert parce qu'il est creux. La pièce s'habite grâce au vide de ses portes et de ses fenêtres.", "ja": "車輪を車輪たらしめるのは、その中心の空である。器が役立つのは、うつろだからだ。部屋が住めるのは、戸と窓の空間があるからだ。"}},
{"id": "n516", "s": "Laozi", "t": {"tr": "Bin fersahlık yolculuk tek bir adımla başlar.", "en": "A journey of a thousand miles begins with a single step.", "de": "Eine Reise von tausend Meilen beginnt mit einem einzigen Schritt.", "es": "Un viaje de mil millas comienza con un solo paso.", "pt": "Uma viagem de mil milhas começa com um único passo.", "fr": "Un voyage de mille lieues commence par un seul pas.", "ja": "千里の道も一歩から始まる。"}},
{"id": "n517", "s": "Zhuangzi", "t": {"tr": "Kelebek olduğunu gören adam mı, yoksa adam olduğunu gören kelebek mi? İkisinin arasındaki sınır, sandığından incedir.", "en": "Was it the man who dreamed he was a butterfly, or the butterfly dreaming it is a man? The line between them is thinner than you think.", "de": "War es der Mensch, der träumte, ein Schmetterling zu sein, oder der Schmetterling, der träumt, ein Mensch zu sein? Die Grenze dazwischen ist dünner, als du denkst.", "es": "¿Fue el hombre que soñó que era mariposa, o la mariposa que sueña que es hombre? La línea entre ambos es más delgada de lo que crees.", "pt": "Foi o homem que sonhou ser borboleta, ou a borboleta que sonha ser homem? A linha entre os dois é mais fina do que pensas.", "fr": "Était-ce l'homme qui rêvait d'être papillon, ou le papillon qui rêve d'être homme? La frontière entre les deux est plus mince que tu ne crois.", "ja": "蝶になった夢を見た人か、それとも人になった夢を見ている蝶か。その境目は、あなたが思うよりも薄い。"}},
{"id": "n518", "s": "Schopenhauer", "t": {"tr": "Yalnızlık, her seçkin ruhun kaderidir. Kalabalıkta kendine ihanet edersin, yalnızlıkta kendine dönersin.", "en": "Solitude is the lot of every distinguished spirit. In the crowd you betray yourself; in solitude you return to yourself.", "de": "Einsamkeit ist das Los aller ausgezeichneten Geister. In der Menge verrätst du dich selbst, in der Einsamkeit kehrst du zu dir zurück.", "es": "La soledad es el destino de todo espíritu distinguido. En la multitud te traicionas; en la soledad vuelves a ti mismo.", "pt": "A solidão é o destino de todo espírito distinto. Na multidão traes-te a ti mesmo; na solidão regressas a ti.", "fr": "La solitude est le lot de tout esprit distingué. Dans la foule tu te trahis; dans la solitude tu reviens à toi.", "ja": "孤独はすぐれた精神の宿命である。群衆の中で人は自分を裏切り、孤独の中で自分に還る。"}},
{"id": "n519", "s": "Schopenhauer", "t": {"tr": "İnsan istediğini yapabilir, ama ne isteyeceğini isteyemez.", "en": "A person can do what they will, but cannot will what they will.", "de": "Der Mensch kann tun, was er will; aber er kann nicht wollen, was er will.", "es": "El ser humano puede hacer lo que quiere, pero no puede querer lo que quiere.", "pt": "A pessoa pode fazer o que quer, mas não pode querer o que quer.", "fr": "L'homme peut faire ce qu'il veut, mais il ne peut vouloir ce qu'il veut.", "ja": "人は欲することを行うことはできるが、何を欲するかを欲することはできない。"}},
{"id": "n520", "s": "Schopenhauer", "t": {"tr": "Sağlıklı bir dilenci, hasta bir kraldan daha mutludur.", "en": "A healthy beggar is happier than a sick king.", "de": "Ein gesunder Bettler ist glücklicher als ein kranker König.", "es": "Un mendigo sano es más feliz que un rey enfermo.", "pt": "Um mendigo saudável é mais feliz do que um rei doente.", "fr": "Un mendiant en bonne santé est plus heureux qu'un roi malade.", "ja": "健康な乞食は、病んだ王よりも幸福である。"}},
{"id": "n521", "s": "Schopenhauer", "t": {"tr": "Hayat sarkaç gibidir: acı ile can sıkıntısı arasında salınır. Arayı doldurmak sanattır.", "en": "Life swings like a pendulum between pain and boredom. Filling the space between is the art.", "de": "Das Leben schwingt wie ein Pendel zwischen Schmerz und Langeweile. Den Zwischenraum zu füllen ist die Kunst.", "es": "La vida oscila como un péndulo entre el dolor y el tedio. Llenar el espacio intermedio es el arte.", "pt": "A vida oscila como um pêndulo entre a dor e o tédio. Preencher o espaço entre as duas é a arte.", "fr": "La vie oscille comme un pendule entre la douleur et l'ennui. Remplir l'espace entre les deux, voilà l'art.", "ja": "人生は苦痛と退屈のあいだを振り子のように揺れる。その間を満たすことが技である。"}},
{"id": "n522", "s": "Schopenhauer", "t": {"tr": "Kitap satın almak güzel olurdu, eğer onları okuyacak zamanı da satın alabilseydik.", "en": "Buying books would be wonderful if we could also buy the time to read them.", "de": "Bücher zu kaufen wäre schön, wenn man die Zeit, sie zu lesen, mitkaufen könnte.", "es": "Comprar libros sería maravilloso si también pudiéramos comprar el tiempo para leerlos.", "pt": "Comprar livros seria maravilhoso se também pudéssemos comprar o tempo para os ler.", "fr": "Acheter des livres serait merveilleux si l'on pouvait aussi acheter le temps de les lire.", "ja": "本を買うのは素晴らしいことだろう。もし読む時間も一緒に買えるのなら。"}},
{"id": "n523", "s": "Carl Jung", "t": {"tr": "Başkalarında seni rahatsız eden her şey, kendini anlamana bir kapı açar.", "en": "Everything that irritates us about others can lead us to an understanding of ourselves.", "de": "Alles, was uns an anderen irritiert, kann uns zu einem Verständnis unserer selbst führen.", "es": "Todo lo que nos irrita de los demás puede llevarnos a comprendernos a nosotros mismos.", "pt": "Tudo o que nos irrita nos outros pode levar-nos a compreender-nos a nós próprios.", "fr": "Tout ce qui nous irrite chez les autres peut nous conduire à nous comprendre nous-mêmes.", "ja": "他人の中であなたを苛立たせるものはすべて、自分自身を理解する扉になりうる。"}},
{"id": "n524", "s": "Carl Jung", "t": {"tr": "Bilinçdışını bilince çıkarmadıkça o hayatını yönetmeye devam eder ve sen buna kader dersin.", "en": "Until you make the unconscious conscious, it will direct your life and you will call it fate.", "de": "Solange du das Unbewusste nicht bewusst machst, wird es dein Leben lenken, und du wirst es Schicksal nennen.", "es": "Hasta que no hagas consciente lo inconsciente, dirigirá tu vida y lo llamarás destino.", "pt": "Enquanto não tornares consciente o inconsciente, ele dirigirá a tua vida e tu chamar-lhe-ás destino.", "fr": "Tant que tu ne rends pas conscient l'inconscient, il dirigera ta vie et tu appelleras cela le destin.", "ja": "無意識を意識化しないかぎり、それはあなたの人生を導き、あなたはそれを運命と呼ぶだろう。"}},
{"id": "n525", "s": "Carl Jung", "t": {"tr": "Işık figürleri hayal ederek değil, karanlığı bilinçli kılarak aydınlanırsın. Bu iş zordur, bu yüzden sevilmez.", "en": "One does not become enlightened by imagining figures of light, but by making the darkness conscious. That work is difficult, and so it is unpopular.", "de": "Man wird nicht erleuchtet, indem man Lichtgestalten imaginiert, sondern indem man das Dunkel bewusst macht. Diese Arbeit ist mühsam und darum unbeliebt.", "es": "Uno no se ilumina imaginando figuras de luz, sino haciendo consciente la oscuridad. Ese trabajo es arduo y por eso resulta impopular.", "pt": "Ninguém se ilumina imaginando figuras de luz, mas tornando consciente a escuridão. Esse trabalho é árduo e por isso é impopular.", "fr": "On ne s'illumine pas en imaginant des figures de lumière, mais en rendant conscientes les ténèbres. Ce travail est ardu, et c'est pourquoi il déplaît.", "ja": "光の像を思い描くことによってではなく、闇を意識化することによって人は照らされる。その仕事は難しく、それゆえ好かれない。"}},
{"id": "n526", "s": "Carl Jung", "t": {"tr": "Kim dışarı bakarsa rüya görür; kim içeri bakarsa uyanır.", "en": "Who looks outside, dreams; who looks inside, awakens.", "de": "Wer nach außen blickt, träumt; wer nach innen blickt, erwacht.", "es": "Quien mira hacia fuera, sueña; quien mira hacia dentro, despierta.", "pt": "Quem olha para fora, sonha; quem olha para dentro, desperta.", "fr": "Qui regarde au dehors rêve; qui regarde au dedans s'éveille.", "ja": "外を見る者は夢を見る。内を見る者は目覚める。"}},
{"id": "n527", "s": "Carl Jung", "t": {"tr": "Olduğun kişi değil, olabileceğin kişi olma ayrıcalığın var.", "en": "You have the privilege of becoming not who you are, but who you could be.", "de": "Du hast das Vorrecht, nicht der zu werden, der du bist, sondern der, der du sein könntest.", "es": "Tienes el privilegio de llegar a ser no quien eres, sino quien podrías ser.", "pt": "Tens o privilégio de te tornares não quem és, mas quem poderias ser.", "fr": "Tu as le privilège de devenir non pas celui que tu es, mais celui que tu pourrais être.", "ja": "あなたには、今のあなたではなく、なりうるあなたになるという特権がある。"}},
{"id": "n528", "s": "Gestalt Yaklaşımı", "t": {"tr": "Ben benim işimi yaparım, sen seninkini. Ben senin beklentilerini karşılamak için bu dünyada değilim, sen de benimkileri.", "en": "I do my thing and you do yours. I am not in this world to live up to your expectations, and you are not here to live up to mine.", "de": "Ich tue mein Ding und du tust deines. Ich bin nicht auf der Welt, um deinen Erwartungen zu entsprechen, und du nicht, um meinen zu entsprechen.", "es": "Yo hago lo mío y tú lo tuyo. No estoy en este mundo para cumplir tus expectativas, ni tú para cumplir las mías.", "pt": "Eu faço o meu e tu fazes o teu. Não estou neste mundo para corresponder às tuas expectativas, nem tu às minhas.", "fr": "Je fais ma part et tu fais la tienne. Je ne suis pas au monde pour répondre à tes attentes, ni toi aux miennes.", "ja": "私は私のことをし、あなたはあなたのことをする。私はあなたの期待に応えるためにこの世にいるのではないし、あなたも私の期待に応えるためにいるのではない。"}},
{"id": "n529", "s": "Gestalt Yaklaşımı", "t": {"tr": "Değişim, olmadığın bir şey olmaya çalıştığında değil, olduğun şey olduğunda gerçekleşir.", "en": "Change happens not when you try to become what you are not, but when you become what you are.", "de": "Wandlung geschieht nicht, wenn du zu werden versuchst, was du nicht bist, sondern wenn du wirst, was du bist.", "es": "El cambio no ocurre cuando intentas ser lo que no eres, sino cuando llegas a ser lo que eres.", "pt": "A mudança não acontece quando tentas ser o que não és, mas quando te tornas aquilo que és.", "fr": "Le changement ne survient pas quand tu tentes de devenir ce que tu n'es pas, mais quand tu deviens ce que tu es.", "ja": "変化は、自分でないものになろうとするときにではなく、自分であるものになるときに起こる。"}},
{"id": "n530", "s": "Gestalt Yaklaşımı", "t": {"tr": "Kaygı, şimdi ile sonra arasındaki boşluktur. Nefesi şimdiye getirdiğinde o boşluk kapanır.", "en": "Anxiety is the gap between now and later. When you bring the breath back to now, the gap closes.", "de": "Angst ist die Lücke zwischen dem Jetzt und dem Später. Wenn du den Atem ins Jetzt zurückholst, schließt sich die Lücke.", "es": "La ansiedad es el hueco entre el ahora y el después. Cuando devuelves la respiración al ahora, ese hueco se cierra.", "pt": "A ansiedade é o vão entre o agora e o depois. Quando trazes a respiração de volta ao agora, esse vão fecha-se.", "fr": "L'anxiété est l'écart entre le maintenant et le plus tard. Quand tu ramènes le souffle au maintenant, l'écart se referme.", "ja": "不安とは、今とあとのあいだの隙間である。呼吸を今に戻すとき、その隙間は閉じる。"}},
{"id": "n531", "s": "Gestalt Yaklaşımı", "t": {"tr": "Rüyandaki her figür sensin. Seni kovalayan da sensin, kaçan da.", "en": "Every figure in your dream is you. The one chasing and the one fleeing are both yours.", "de": "Jede Gestalt in deinem Traum bist du. Der Verfolger und der Fliehende sind beide du.", "es": "Cada figura de tu sueño eres tú. El que persigue y el que huye son ambos tuyos.", "pt": "Cada figura do teu sonho és tu. O que persegue e o que foge são ambos teus.", "fr": "Chaque figure de ton rêve, c'est toi. Celui qui poursuit et celui qui fuit sont tous deux toi.", "ja": "夢に現れるすべての姿はあなたである。追う者も、逃げる者も、どちらもあなただ。"}},
{"id": "n532", "s": "Gestalt Yaklaşımı", "t": {"tr": "Tamamlanmamış olan geri döner. Bitirilmeyen bir cümle, kapatılmayan bir veda, hep kapıyı çalar.", "en": "What is unfinished returns. An unspoken sentence, a goodbye never closed, keeps knocking at the door.", "de": "Was unvollendet bleibt, kehrt zurück. Ein nicht zu Ende gesprochener Satz, ein nie geschlossener Abschied, klopft immer wieder an.", "es": "Lo inconcluso regresa. Una frase que no se terminó, una despedida que no se cerró, siempre vuelve a llamar a la puerta.", "pt": "O que fica por terminar regressa. Uma frase não acabada, uma despedida nunca fechada, batem sempre à porta.", "fr": "Ce qui reste inachevé revient. Une phrase non finie, un adieu jamais clos, frappent encore à la porte.", "ja": "終わっていないものは戻ってくる。言い終えなかった一文、閉じられなかった別れは、いつまでも扉を叩く。"}},
];

// EŞİT AĞIRLIK (Eyl 2026, kullanıcı: "Schopenhauer, Jung, Yunus Emre, Aşık Veysel
// eşit ağırlıkta olsun, hep aynı kişiler çıkıyor"). Eskiden QUOTES içinden düz
// seçiliyordu; havuzun ~%40'ı Mevlana olduğu için hep aynı isimler geliyordu.
// Şimdi önce KAYNAK (eşit şans), sonra o kaynağın sözü seçilir. Gruplama
// Bitkiler/Taşlar/Hayvan'daki buildQuotePool ile AYNI (apps/*/src/utils/quotePool.ts).
export const QUOTE_GROUP = {
  "Dhammapada": "Buddha",
  "Zen Geleneği": "Buddha",
  "Zhuangzi": "Laozi",
  "Seneca": "Epiktetos",
  "Marcus Aurelius": "Epiktetos",
};
// seedA: kaynak seçimi, seedB: kaynak içindeki söz (ikisi ayrı hash olmalı,
// yoksa aynı kaynaktan hep aynı sıradaki söz gelirdi).
export function pickBalancedQuote(seedA, seedB) {
  const groups = {};
  for (const q of QUOTES) { const g = QUOTE_GROUP[q.s] || q.s; (groups[g] = groups[g] || []).push(q); }
  const names = Object.keys(groups).sort();
  const g = groups[names[Math.abs(seedA) % names.length]];
  return g[Math.abs(seedB) % g.length];
}
